  1→package com.danawa.search.analysis.korean
  2→
  3→import com.danawa.search.analysis.dict.ProductNameDictionary
  4→import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag
  5→import com.danawa.search.analysis.korean.PosTagProbEntry.TagProb
  6→import com.danawa.search.analysis.product.AnalyzeExceedException
  7→import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.ALPHA
  8→import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.NUMBER
  9→import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.SYMBOL
 10→import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.getType
 11→import com.danawa.util.CharVector
 12→import org.apache.logging.log4j.LogManager
 13→import java.util.*
 14→
 15→open class KoreanWordExtractor {
 16→
 17→    private var koreanDict: ProductNameDictionary
 18→
 19→    private var tabular: Array<Array<PosTagProbEntry?>>
 20→    private var status: IntArray
 21→    private var josaSet: MutableSet<CharVector>
 22→
 23→    var fastResultOption: Boolean = true
 24→    var fastResultFound: Boolean = false
 25→    var remnantOffset: Int = 0
 26→    var remnantLength: Int = 0
 27→    var isUnicode: Boolean = false
 28→    var charVector: CharVector = CharVector()
 29→    var tabularStringer: TabularStringer
 30→    var entryStringer: EntryStringer
 31→
 32→    private val queue: PriorityQueue<ExtractedEntry> = PriorityQueue(8, Comparator { o1, o2 ->
 33→        (o2.totalScore() - o1.totalScore()).toInt()
 34→    })
 35→
 36→    private val result: MutableList<ExtractedEntry> = ArrayList()
 37→
 38→    protected var source: CharArray = CharArray(0)
 39→    protected var offset: Int = 0
 40→    protected var length: Int = 0
 41→
 42→    @JvmOverloads
 43→    constructor(koreanDict: ProductNameDictionary, tabularSize: Int = 20) {
 44→        tabular = Array(tabularSize) { row -> arrayOfNulls(row + 2) }
 45→        status = IntArray(tabularSize)
 46→        this.koreanDict = koreanDict
 47→        josaSet = HashSet()
 48→        val josaList = "은 는 이 가 을 를 에 과 와 의 로 만 께 에게 에서 으로 부터 라서 라고 께서 한테 처럼 같이 라는 하며 하고 까지 이라고 이라는 이라도 이라면 에서도 이기도"
 49→        val jl = josaList.split(Regex("\\s"))
 50→        for (j in jl) {
 51→            josaSet.add(CharVector(j))
 52→        }
 53→        tabularStringer = TabularStringer()
 54→        entryStringer = EntryStringer()
 55→    }
 56→
 57→    fun dictionary(): ProductNameDictionary = koreanDict
 58→
 59→    fun setKoreanDic(koreanDict: ProductNameDictionary) {
 60→        this.koreanDict = koreanDict
 61→    }
 62→
 63→    private fun doSegment(): ExtractedEntry? {
 64→        val cv = CharVector(source, offset, length)
 65→        if (length == 1) {
 66→            val tag = koreanDict.find(cv)
 67→            if (tag != null) {
 68→                return ExtractedEntry(length - 1, length, tag[0], offset)
 69→            }
 70→            if (isDigit(cv)) {
 71→                return ExtractedEntry(length - 1, length, TagProb.DIGIT, offset)
 72→            } else if (isSymbol(cv)) {
 73→                return ExtractedEntry(length - 1, length, TagProb.SYMBOL, offset)
 74→            }
 75→            return ExtractedEntry(length - 1, length, TagProb.UNK, offset)
 76→        }
 77→        val tag = koreanDict.find(cv)
 78→        if (tag != null) {
 79→            return ExtractedEntry(length - 1, length, tag[0], offset)
 80→        }
 81→        val start = length - 1
 82→        for (row in start downTo 0) {
 83→            for (column in row + 1 downTo 1) {
 84→                cv.init(offset + row - column + 1, column)
 85→                var tagList: List<TagProb>?
 86→                var isAlpha = false
 87→                if (isDigit(cv)) {
 88→                    tabular[row][column] = PosTagProbEntry(TagProb.DIGIT)
 89→                    status[row]++
 90→                } else if (isSymbol(cv)) {
 91→                    tabular[row][column] = PosTagProbEntry(TagProb.SYMBOL)
 92→                    status[row]++
 93→                } else {
 94→                    if (isAlpha(cv)) {
 95→                        if (column == 1) {
 96→                            tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
 97→                            continue
 98→                        }
 99→                        isAlpha = true
100→                    }
101→                    tagList = koreanDict.find(cv)
102→                    if (tagList != null) {
103→                        if (column == length) {
104→                            return ExtractedEntry(row, column, tagList[0], offset)
105→                        }
106→                        var chainedEntry: PosTagProbEntry? = null
107→                        for (i in tagList.indices) {
108→                            val tagProb = tagList[i]
109→                            if (i == 0) {
110→                                chainedEntry = PosTagProbEntry(tagProb)
111→                                tabular[row][column] = chainedEntry
112→                            } else {
113→                                chainedEntry = chainedEntry!!.next(tagProb)
114→                            }
115→                        }
116→                        status[row]++
117→                    } else {
118→                        if (isAlpha) {
119→                            tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
120→                        } else {
121→                            tabular[row][column] = null
122→                        }
123→                    }
124→
125→                    if (column < 3) {
126→                        if (josaSet.contains(cv)) {
127→                            val entry = PosTagProbEntry(TagProb.JOSA)
128→                            if (tabular[row][column] == null) {
129→                                tabular[row][column] = entry
130→                            } else {
131→                                entry.next = tabular[row][column]
132→                                tabular[row][column] = entry
133→                            }
134→                            status[row]++
135→                        }
136→                    }
137→                }
138→            }
139→        }
140→        return null
141→    }
142→
143→    private fun isUnicode(buffer: CharArray, offset: Int, length: Int): Boolean {
144→        for (inx in 0 until length) {
145→            val ch = buffer[offset + inx]
146→            if (ch.code > 127) {
147→                return true
148→            }
149→        }
150→        return false
151→    }
152→
153→    private fun isDigit(cv: CharVector): Boolean {
154→        for (i in 0 until cv.length()) {
155→            val ch = cv[i]
156→            if (ch < '0' || ch > '9') {
157→                return false
158→            }
159→        }
160→        return true
161→    }
162→
163→    private fun isAlpha(cv: CharVector): Boolean {
164→        for (i in 0 until cv.length()) {
165→            val ch = cv[i]
166→            if (!((ch in 'a'..'z') || (ch in 'A'..'Z'))) {
167→                return false
168→            }
169→        }
170→        return true
171→    }
172→
173→    private fun isSymbol(cv: CharVector): Boolean {
174→        for (i in 0 until cv.length()) {
175→            val chInt = cv[i].code
176→            if (Character.isLetterOrDigit(chInt)) {
177→                return false
178→            }
179→        }
180→        return true
181→    }
182→
183→    private fun makeResult() {
184→        var headRow = -1
185→        for (row in length - 1 downTo 0) {
186→            if (status[row] > 0) {
187→                headRow = row
188→                break
189→            }
190→        }
191→
192→        try {
193→            if (headRow == -1) {
194→                addResult(ExtractedEntry(length - 1, length, TagProb.UNK, offset))
195→                return
196→            }
197→            if (headRow < length - 1) {
198→                val tail = ExtractedEntry(length - 1, length - 1 - headRow, TagProb.UNK, offset)
199→                connectAllTo(headRow, tail)
200→            } else {
201→                connectAllTo(headRow, null)
202→            }
203→            var tail: ExtractedEntry?
204→            while (queue.poll().also { tail = it } != null) {
205→                val t = tail!!
206→                val connectRow = t.row() - t.column()
207→                if (status[connectRow] > 0) {
208→                    connectAllTo(connectRow, t)
209→                } else {
210→                    connectTo(null, connectRow, -1, t)
211→                }
212→            }
213→        } catch (e: AnalyzeExceedException) {
214→            logger.debug("Analyze exceed : " + e.message)
215→        }
216→    }
217→
218→    @Throws(AnalyzeExceedException::class)
219→    private fun connectAllTo(headRow: Int, tail: ExtractedEntry?): Int {
220→        val rowData = tabular[headRow]
221→        var found = 0
222→        for (headColumn in headRow + 1 downTo 1) {
223→            if (rowData[headColumn] != null) {
224→                val tagEntry = rowData[headColumn]!!
225→                entryStringer.set(tagEntry, source, headRow, headColumn, offset)
226→                if (tagEntry.tagProb!!.posTag() != PosTag.ALPHA) {
227→                    connectTo(tagEntry, headRow, headColumn, tail)
228→                    found++
229→                }
230→            }
231→            if (found >= status[headRow]) {
232→                break
233→            }
234→        }
235→        if (!isUnicode) {
236→            var inx = 0
237→            while (inx < result.size) {
238→                if (result[inx].last().posTag() == PosTag.UNK) {
239→                    result.removeAt(inx)
240→                    inx--
241→                }
242→                inx++
243→            }
244→        }
245→        return found
246→    }
247→
248→    @Throws(AnalyzeExceedException::class)
249→    private fun connectTo(headTagEntry: PosTagProbEntry?, headRow: Int, headColumn: Int, tail: ExtractedEntry?): Int {
250→        var currentEntry = headTagEntry
251→        if (tail == null) {
252→            var found = 0
253→            while (currentEntry != null) {
254→                val headEntry = ExtractedEntry(headRow, headColumn, currentEntry.get()!!, offset)
255→                if (headEntry.row() - headEntry.column() < 0) {
256→                    addResult(headEntry)
257→                } else {
258→                    addQueue(headEntry)
259→                }
260→                currentEntry = currentEntry.next
261→                found++
262→            }
263→            return found
264→        }
265→
266→        if (currentEntry == null) {
267→            for (column in 1..headRow + 1) {
268→                val row2 = headRow - column
269→                if (row2 < 0 || status[row2] > 0) {
270→                    // 2014-1-27처리..
271→                }
272→            }
273→            return 1
274→        }
275→
276→        var found = 0
277→        while (currentEntry != null) {
278→            if (isConnectableByRule(currentEntry.get()!!, headRow, headColumn, tail)) {
279→                val newTail = modifyAndConnect(currentEntry.get()!!, headRow, headColumn, tail)
280→                if (newTail != null) {
281→                    if (newTail.row() - newTail.column() < 0) {
282→                        addResult(newTail)
283→                    } else {
284→                        addQueue(newTail)
285→                    }
286→                    found++
