package com.danawa.search.analysis.korean

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag
import com.danawa.search.analysis.korean.PosTagProbEntry.TagProb
import com.danawa.search.analysis.product.AnalyzeExceedException
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.ALPHA
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.NUMBER
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.SYMBOL
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.getType
import com.danawa.util.CharVector
import org.apache.logging.log4j.LogManager
import java.util.*

open class KoreanWordExtractor {

    private var koreanDict: ProductNameDictionary

    private var tabular: Array<Array<PosTagProbEntry?>>
    private var status: IntArray
    private var josaSet: MutableSet<CharVector>

    var fastResultOption: Boolean = true
    var fastResultFound: Boolean = false
    var remnantOffset: Int = 0
    var remnantLength: Int = 0
    var isUnicode: Boolean = false
    var charVector: CharVector = CharVector()
    var tabularStringer: TabularStringer
    var entryStringer: EntryStringer

    private val queue: PriorityQueue<ExtractedEntry> = PriorityQueue(8, Comparator { o1, o2 ->
        (o2.totalScore() - o1.totalScore()).toInt()
    })

    private val result: MutableList<ExtractedEntry> = ArrayList()

    protected var source: CharArray = CharArray(0)
    protected var offset: Int = 0
    protected var length: Int = 0

    @JvmOverloads
    constructor(koreanDict: ProductNameDictionary, tabularSize: Int = 20) {
        tabular = Array(tabularSize) { row -> arrayOfNulls(row + 2) }
        status = IntArray(tabularSize)
        this.koreanDict = koreanDict
        josaSet = HashSet()
        val josaList = "은 는 이 가 을 를 에 과 와 의 로 만 께 에게 에서 으로 부터 라서 라고 께서 한테 처럼 같이 라는 하며 하고 까지 이라고 이라는 이라도 이라면 에서도 이기도"
        val jl = josaList.split(Regex("\\s"))
        for (j in jl) {
            josaSet.add(CharVector(j))
        }
        tabularStringer = TabularStringer()
        entryStringer = EntryStringer()
    }

    fun dictionary(): ProductNameDictionary = koreanDict

    fun setKoreanDic(koreanDict: ProductNameDictionary) {
        this.koreanDict = koreanDict
    }

    private fun doSegment(): ExtractedEntry? {
        val cv = CharVector(source, offset, length)
        if (length == 1) {
            val tag = koreanDict.find(cv)
            if (tag != null) {
                return ExtractedEntry(length - 1, length, tag[0], offset)
            }
            if (isDigit(cv)) {
                return ExtractedEntry(length - 1, length, TagProb.DIGIT, offset)
            } else if (isSymbol(cv)) {
                return ExtractedEntry(length - 1, length, TagProb.SYMBOL, offset)
            }
            return ExtractedEntry(length - 1, length, TagProb.UNK, offset)
        }
        val tag = koreanDict.find(cv)
        if (tag != null) {
            return ExtractedEntry(length - 1, length, tag[0], offset)
        }
        val start = length - 1
        for (row in start downTo 0) {
            for (column in row + 1 downTo 1) {
                cv.init(offset + row - column + 1, column)
                var tagList: List<TagProb>?
                var isAlpha = false
                if (isDigit(cv)) {
                    tabular[row][column] = PosTagProbEntry(TagProb.DIGIT)
                    status[row]++
                } else if (isSymbol(cv)) {
                    tabular[row][column] = PosTagProbEntry(TagProb.SYMBOL)
                    status[row]++
                } else {
                    if (isAlpha(cv)) {
                        if (column == 1) {
                            tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
                            continue
                        }
                        isAlpha = true
                    }
                    tagList = koreanDict.find(cv)
                    if (tagList != null) {
                        if (column == length) {
                            return ExtractedEntry(row, column, tagList[0], offset)
                        }
                        var chainedEntry: PosTagProbEntry? = null
                        for (i in tagList.indices) {
                            val tagProb = tagList[i]
                            if (i == 0) {
                                chainedEntry = PosTagProbEntry(tagProb)
                                tabular[row][column] = chainedEntry
                            } else {
                                chainedEntry = chainedEntry!!.next(tagProb)
                            }
                        }
                        status[row]++
                    } else {
                        if (isAlpha) {
                            tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
                        } else {
                            tabular[row][column] = null
                        }
                    }

                    if (column < 3) {
                        if (josaSet.contains(cv)) {
                            val entry = PosTagProbEntry(TagProb.JOSA)
                            if (tabular[row][column] == null) {
                                tabular[row][column] = entry
                            } else {
                                entry.next = tabular[row][column]
                                tabular[row][column] = entry
                            }
                            status[row]++
                        }
                    }
                }
            }
        }
        return null
    }

    private fun isUnicode(buffer: CharArray, offset: Int, length: Int): Boolean {
        for (inx in 0 until length) {
            val ch = buffer[offset + inx]
            if (ch.code > 127) {
                return true
            }
        }
        return false
    }

    private fun isDigit(cv: CharVector): Boolean {
        for (i in 0 until cv.length()) {
            val ch = cv[i]
            if (ch < '0' || ch > '9') {
                return false
            }
        }
        return true
    }

    private fun isAlpha(cv: CharVector): Boolean {
        for (i in 0 until cv.length()) {
            val ch = cv[i]
            if (!((ch in 'a'..'z') || (ch in 'A'..'Z'))) {
                return false
            }
        }
        return true
    }

    private fun isSymbol(cv: CharVector): Boolean {
        for (i in 0 until cv.length()) {
            val chInt = cv[i].code
            if (Character.isLetterOrDigit(chInt)) {
                return false
            }
        }
        return true
    }

    private fun makeResult() {
        var headRow = -1
        for (row in length - 1 downTo 0) {
            if (status[row] > 0) {
                headRow = row
                break
            }
        }

        try {
            if (headRow == -1) {
                addResult(ExtractedEntry(length - 1, length, TagProb.UNK, offset))
                return
            }
            if (headRow < length - 1) {
                val tail = ExtractedEntry(length - 1, length - 1 - headRow, TagProb.UNK, offset)
                connectAllTo(headRow, tail)
            } else {
                connectAllTo(headRow, null)
            }
            var tail: ExtractedEntry?
            while (queue.poll().also { tail = it } != null) {
                val t = tail!!
                val connectRow = t.row() - t.column()
                if (status[connectRow] > 0) {
                    connectAllTo(connectRow, t)
                } else {
                    connectTo(null, connectRow, -1, t)
                }
            }
        } catch (e: AnalyzeExceedException) {
            logger.debug("Analyze exceed : " + e.message)
        }
    }

    @Throws(AnalyzeExceedException::class)
    private fun connectAllTo(headRow: Int, tail: ExtractedEntry?): Int {
        val rowData = tabular[headRow]
        var found = 0
        for (headColumn in headRow + 1 downTo 1) {
            if (rowData[headColumn] != null) {
                val tagEntry = rowData[headColumn]!!
                entryStringer.set(tagEntry, source, headRow, headColumn, offset)
                if (tagEntry.tagProb!!.posTag() != PosTag.ALPHA) {
                    connectTo(tagEntry, headRow, headColumn, tail)
                    found++
                }
            }
            if (found >= status[headRow]) {
                break
            }
        }
        if (!isUnicode) {
            var inx = 0
            while (inx < result.size) {
                if (result[inx].last().posTag() == PosTag.UNK) {
                    result.removeAt(inx)
                    inx--
                }
                inx++
            }
        }
        return found
    }

    @Throws(AnalyzeExceedException::class)
    private fun connectTo(headTagEntry: PosTagProbEntry?, headRow: Int, headColumn: Int, tail: ExtractedEntry?): Int {
        var currentEntry = headTagEntry
        if (tail == null) {
            var found = 0
            while (currentEntry != null) {
                val headEntry = ExtractedEntry(headRow, headColumn, currentEntry.get()!!, offset)
                if (headEntry.row() - headEntry.column() < 0) {
                    addResult(headEntry)
                } else {
                    addQueue(headEntry)
                }
                currentEntry = currentEntry.next
                found++
            }
            return found
        }

        if (currentEntry == null) {
            for (column in 1..headRow + 1) {
                val row2 = headRow - column
                if (row2 < 0 || status[row2] > 0) {
                    // 2014-1-27처리..
                }
            }
            return 1
        }

        var found = 0
        while (currentEntry != null) {
            if (isConnectableByRule(currentEntry.get()!!, headRow, headColumn, tail)) {
                val newTail = modifyAndConnect(currentEntry.get()!!, headRow, headColumn, tail)
                if (newTail != null) {
                    if (newTail.row() - newTail.column() < 0) {
                        addResult(newTail)
                    } else {
                        addQueue(newTail)
                    }
                    found++
                }
            }
            currentEntry = currentEntry.next
        }
        return found
    }

    @Throws(AnalyzeExceedException::class)
    protected open fun addQueue(entry: ExtractedEntry) {
        if (fastResultFound) {
            return
        }
        queue.add(entry)
        if (queue.size >= QUEUE_MAX) {
            throw AnalyzeExceedException("Queue size exceed ${queue.size} : ${String(source)}")
        }
    }

    @Throws(AnalyzeExceedException::class)
    protected open fun addResult(entry: ExtractedEntry) {
        val e = finalCheck(entry) ?: return
        result.add(entry)

        if (fastResultOption && length > 6) {
            fastResultFound = true
            queue.clear()
        }

        if (result.size >= RESULT_MAX) {
            val tmpResult = getHighResult()
            result.clear()
            if (tmpResult != null) {
                result.add(tmpResult)
            }
        }
    }

    fun setInput(buffer: CharArray, length: Int): Int {
        return setInput(buffer, 0, length)
    }

    fun setInput(buffer: CharArray, offset: Int, length: Int): Int {
        var len = length
        remnantOffset = 0
        remnantLength = 0
        isUnicode = isUnicode(buffer, offset, len)
        Arrays.fill(status, 0)
        for (row in tabular.indices) {
            for (col in tabular[row].indices) {
                tabular[row][col] = null
            }
        }
        result.clear()

        var type: String? = null
        var ptype: String? = null
        var pptype: String? = null
        if (len > tabular.size) {
            logger.trace("LENGTH IS OVER THAN {} / {} / {}", len, tabular.size, offset)
            for (inx in offset + len downTo offset + 1) {
                pptype = ptype
                ptype = type
                type = getType(buffer[inx - 1].code)
                if (logger.isTraceEnabled) {
                    logger.trace("PP:{}/P:{}/T:{}/C:{} {} [{}/{}/{} | {}/{}/{}]", pptype, ptype, type, buffer[inx - 1],
                        inx - offset,
                        pptype != null && (pptype != ALPHA && pptype != NUMBER),
                        inx < buffer.size && ptype == SYMBOL && buffer[inx] != '&',
                        type != null, pptype != null,
                        inx < buffer.size && ptype == SYMBOL && buffer[inx] != '&',
                        type != null && (type != ALPHA && type != NUMBER))
                }
                if (((pptype != null && (pptype != ALPHA && pptype != NUMBER))
                            && (inx < buffer.size && ptype == SYMBOL && buffer[inx] != '&')
                            && (type != null))
                    || ((pptype != null) && (inx < buffer.size && ptype == SYMBOL && buffer[inx] != '&')
                            && (type != null && (type != ALPHA && type != NUMBER)))) {
                    logger.trace("LENGTH:{} / {}", len - offset, tabular.size)
                    len = inx - offset
                    if (len <= tabular.size) {
                        logger.trace("BREAK INTO {}", len)
                        break
                    }
                }
            }
            if (len > tabular.size) {
                type = null
                for (inx in offset until (offset + len)) {
                    ptype = type
                    type = getType(buffer[inx].code)
                    if (ptype != null && (
                                ((type == ALPHA || type == NUMBER || type == SYMBOL)
                                        && !(ptype == ALPHA || ptype == NUMBER || ptype == SYMBOL))
                                        || (!(type == ALPHA || type == NUMBER || type == SYMBOL)
                                        && (ptype == ALPHA || ptype == NUMBER || ptype == SYMBOL)))) {
                        len = inx - offset
                    }
                }
            }

            if (len > tabular.size) {
                if (logger.isTraceEnabled) {
                    logger.trace("CUT TABULAR SIZE : {}/ {} -> {}", len, String(buffer, offset, len), String(buffer, offset, tabular.size))
                }
                remnantOffset = tabular.size
                remnantLength = len - tabular.size
                len = tabular.size
            }
        }
        return setInput0(buffer, offset, len)
    }

    private fun setInput0(buffer: CharArray, offset: Int, length: Int): Int {
        this.source = buffer
        queue.clear()
        result.clear()
        this.offset = offset
        this.length = length
        fastResultFound = false
        return length
    }

    fun extract(): ExtractedEntry {
        tabularStringer.set(tabular, source, status, length, offset)
        ExtractedEntry.source = source
        val e = extract0()!!
        var last = e.last()
        while (remnantLength > 0) {
            val len = Math.min(tabular.size, remnantLength)
            setInput0(source, remnantOffset, len)
            val r = extract0()
            if (r != null) {
                if (!(last.offset() + last.column() > r.offset())) {
                    last.next(r)
                    last = r.last()
                }
            }
            remnantOffset += len
            remnantLength -= len
        }
        return e
    }

    fun extract0(): ExtractedEntry? {
        val e = doSegment()
        if (e != null) {
            return e
        }
        makeResult()
        return getBestResult()
    }

    fun getAllResult(): List<ExtractedEntry> = result

    private fun getHighResult(): ExtractedEntry? {
        var highEntry: ExtractedEntry? = null
        for (k in result.indices) {
            var entry: ExtractedEntry? = result[k]
            entry = finalCheck(entry!!)
            if (entry == null) {
                continue
            }
            charVector.init(source, entry.offset(), entry.column())

            if (highEntry == null) {
                highEntry = entry
            } else {
                if (isBetterThan(entry, highEntry)) {
                    highEntry = entry
                }
            }
        }
        return highEntry
    }

    fun getBestResult(): ExtractedEntry {
        var bestEntry = getHighResult()
        if (bestEntry == null) {
            bestEntry = ExtractedEntry(length - 1, length, TagProb.UNK, offset)
            return bestEntry
        }
        return bestEntry
    }

    fun getTabularSize(): Int = tabular.size

    protected open fun isConnectableByRule(headTagProb: TagProb, headRow: Int, headColumn: Int, tail: ExtractedEntry): Boolean {
        if (headTagProb.posTag() == PosTag.DIGIT && tail.tagProb().posTag() == PosTag.DIGIT) {
            return false
        }
        if (headTagProb.posTag() == PosTag.ALPHA && tail.tagProb().posTag() == PosTag.ALPHA) {
            return false
        }
        if (headTagProb.posTag() == PosTag.SYMBOL && tail.tagProb().posTag() == PosTag.SYMBOL) {
            return false
        }
        if (headTagProb.posTag() != PosTag.ALPHA && headTagProb.posTag() != PosTag.DIGIT && headTagProb.posTag() != PosTag.SYMBOL) {
            if (tail.tagProb().posTag() == PosTag.J && tail.column() == 1) {
                val ch = source[offset + tail.row() - tail.column() + 1]
                if (ch == '\uC740' || ch == '\uC774' || ch == '\uC744' || ch == '\uACFC') {
                    if (!MorphUtil.hasLastElement(source[offset + headRow])) {
                        return false
                    }
                } else if (ch == '\uB294' || ch == '\uAC00' || ch == '\uB97C' || ch == '\uC640') {
                    if (MorphUtil.hasLastElement(source[offset + headRow])) {
                        return false
                    }
                }
            }
        }

        if (headColumn == 1 && tail.column() == 1 && headTagProb.posTag() != PosTag.J && tail.posTag() != PosTag.J) {
            if (tabular[tail.row()][tail.column() + headColumn] != null) {
                return false
            }
        }
        return true
    }

    protected open fun modifyAndConnect(tagProb: TagProb, row: Int, column: Int, tail: ExtractedEntry): ExtractedEntry? {
        val newEntry = ExtractedEntry(row, column, tagProb, offset)
        return newEntry.next(tail)
    }

    private fun finalCheck(headEntry: ExtractedEntry): ExtractedEntry? {
        if (headEntry.posTag() == PosTag.J) {
            return null
        }

        var count = 0
        if (headEntry.entryCount() >= 2) {
            var current: ExtractedEntry? = headEntry
            while (current != null) {
                if (current.column() > 1) {
                    break
                } else {
                    count++
                }
                current = current.next()
            }
        }

        if (count == headEntry.entryCount()) {
            if (headEntry.last().posTag() == PosTag.J) {
                return headEntry
            }
            return null
        }
        return headEntry
    }

    protected open fun isBetterThan(entry: ExtractedEntry, bestEntry: ExtractedEntry): Boolean {
        if (entry.totalScore() > bestEntry.totalScore()) {
            return true
        }
        return false
    }

    class ExtractedEntry : Cloneable {
        private var row: Int
        private var column: Int
        private var tagProb: TagProb
        private var next: ExtractedEntry? = null
        private var score: Double = 0.0
        private var extracted: Boolean = false
        private var _offset: Int = 0

        constructor(row: Int, column: Int, tagProb: TagProb) : this(row, column, tagProb, 0.0)

        constructor(row: Int, column: Int, tagProb: TagProb, scoreAdd: Double) {
            this.row = row
            this.column = column
            this.tagProb = tagProb
            this.score += (tagProb.prob() + scoreAdd)
        }

        constructor(row: Int, column: Int, tagProb: TagProb, offset: Int) {
            this.row = row
            this.column = column
            this.tagProb = tagProb
            this.score += tagProb.prob()
            this._offset = offset
        }

        fun tagProb(): TagProb = tagProb

        fun posTag(): PosTag = tagProb.posTag()

        fun tagProb(tagProb: TagProb) {
            this.score -= this.tagProb.prob()
            this.tagProb = tagProb
            this.score += tagProb.prob()
        }

        fun offset(): Int = _offset + row - column + 1

        fun row(): Int = row
        fun row(row: Int) { this.row = row }

        fun column(): Int = column
        fun column(column: Int) { this.column = column }

        fun addScore(score: Int) { this.score += score }

        fun totalScore(): Double = score

        fun entryCount(): Int {
            var nextEntry: ExtractedEntry? = this
            var count = 0
            while (nextEntry != null) {
                count++
                nextEntry = nextEntry.next
            }
            return count
        }

        fun charSize(): Int = column

        fun next(): ExtractedEntry? = next

        fun last(): ExtractedEntry {
            var l: ExtractedEntry = this
            while (true) {
                if (l.next() == null) {
                    return l
                } else {
                    l = l.next()!!
                }
            }
        }

        fun setNext(next: ExtractedEntry?) { this.next = next }

        fun next(next: ExtractedEntry?): ExtractedEntry {
            this.next = next
            if (next != null) {
                this.score += next.score
            }
            return this
        }

        fun isExtracted(): Boolean = extracted
        fun setExtracted(extracted: Boolean) { this.extracted = extracted }

        fun getChainedString(): String {
            return if (next == null) {
                toString()
            } else {
                toString() + " + " + next!!.getChainedString()
            }
        }

        fun getChainedShortString(source: CharArray): String {
            return if (next == null) {
                toShortString(source)
            } else {
                toShortString(source) + " + " + next!!.getChainedShortString(source)
            }
        }

        fun getChainedString(source: CharArray): String {
            return if (next == null) {
                toDetailString(source)
            } else {
                toDetailString(source) + " + " + next!!.getChainedString(source)
            }
        }

        public override fun clone(): ExtractedEntry {
            return try {
                super.clone() as ExtractedEntry
            } catch (e: CloneNotSupportedException) {
                logger.error("", e)
                this
            }
        }

        override fun toString(): String {
            return "(${String(source, row + _offset - column + 1, column)}:${row + _offset},$column):$tagProb:$score"
        }

        fun toWord(source: CharArray): String = String(source, row + _offset - column + 1, column)

        fun toShortString(source: CharArray): String {
            return "${String(source, row + _offset - column + 1, column)}:${tagProb.toShortString()}"
        }

        fun toDetailString(source: CharArray): String {
            return try {
                "${String(source, row + _offset - column + 1, column)}(${row + _offset},$column):$tagProb:$score"
            } catch (e: Exception) {
                logger.debug("{} ({},{})", String(source), row + _offset - column + 1, column)
                throw RuntimeException()
            }
        }

        companion object {
            @JvmStatic
            var source: CharArray = CharArray(0)
        }
    }

    class EntryStringer {
        private var entry: PosTagProbEntry? = null
        private var row: Int = 0
        private var column: Int = 0

        fun set(entry: PosTagProbEntry, source: CharArray, row: Int, column: Int, offset: Int) {
            this.entry = entry
            this.row = row
            this.column = column
            Companion.source = source
            Companion.offset = offset
        }

        override fun toString(): String {
            val sb = StringBuilder()
            sb.append(String(source, row - column + 1 + offset, column)).append("[")
            var e = entry
            while (e != null) {
                sb.append(e.get())
                e = e.next()
            }
            sb.append("]")
            return sb.toString()
        }

        companion object {
            private var source: CharArray = CharArray(0)
            private var offset: Int = 0
        }
    }

    class TabularStringer {
        fun set(tabular: Array<Array<PosTagProbEntry?>>, source: CharArray, status: IntArray, length: Int, offset: Int) {
            Companion.tabular = tabular
            Companion.source = source
            Companion.status = status
            Companion.length = length
            Companion.offset = offset
        }

        override fun toString(): String {
            val ret = StringBuilder()
            for (row in 0 until length) {
                val el = tabular[row]
                val count = status[row]
                val sb = StringBuilder()
                sb.append("").append(row).append(" ")
                    .append("{ ").append(count).append(" }").append(" | ")
                for (column in 1..row + 1) {
                    val e = el[column]
                    sb.append(String(source, row - column + 1 + offset, column)).append("[")
                    var entry = e
                    while (entry != null) {
                        sb.append(entry.get())
                        entry = entry.next()
                    }
                    sb.append("]").append(" | ")
                }
                ret.append("\r\n").append(sb)
            }
            return ret.toString()
        }

        companion object {
            private var source: CharArray = CharArray(0)
            private var tabular: Array<Array<PosTagProbEntry?>> = emptyArray()
            private var status: IntArray = IntArray(0)
            private var length: Int = 0
            private var offset: Int = 0
        }
    }

    companion object {
        private val logger = LogManager.getLogger(KoreanWordExtractor::class.java)
        private const val QUEUE_MAX = 200
        private const val RESULT_MAX = 10
    }
}

package com.danawa.search.analysis.product

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.korean.KoreanWordExtractor
import com.danawa.search.analysis.korean.KoreanWordExtractor.ExtractedEntry
import com.danawa.util.CharVector

import org.apache.logging.log4j.LogManager
import org.apache.lucene.analysis.Tokenizer
import org.apache.lucene.analysis.tokenattributes.CharTermAttribute
import org.apache.lucene.analysis.tokenattributes.OffsetAttribute
import org.apache.lucene.analysis.tokenattributes.TokenInfoAttribute
import org.apache.lucene.analysis.tokenattributes.TypeAttribute
import org.apache.lucene.util.AttributeFactory

import java.io.IOException

class ProductNameTokenizer : Tokenizer {

    private val termAtt = addAttribute(CharTermAttribute::class.java)
    private val tokenAtt = addAttribute(TokenInfoAttribute::class.java)
    private val offsetAtt = addAttribute(OffsetAttribute::class.java)
    private val typeAtt = addAttribute(TypeAttribute::class.java)

    private var baseOffset = 0
    private var position = 0
    private var extLength = 0
    private var readLength = 0
    private var tokenLength = 0
    private var finalOffset = 0

    private var buffer: CharArray? = null
    private var backBuffer = arrayOf(CharArray(IO_BUFFER_SIZE), CharArray(IO_BUFFER_SIZE))
    private var entry: ExtractedEntry? = null
    private var extractor: KoreanWordExtractor? = null
    private var chrCurrent: Char = 0.toChar()
    private var typeCurrent: String? = null
    private var exportTerm: Boolean = false
    private var tabularFull: Boolean = false

    constructor(dictionary: ProductNameDictionary?, exportTerm: Boolean) {
        if (dictionary != null) {
            extractor = KoreanWordExtractor(dictionary)
            tokenAtt.dictionary(dictionary)
        }
        this.exportTerm = exportTerm
    }

    constructor(factory: AttributeFactory) : super(factory)

    protected fun isTokenChar(c1: Int, c2: Int): Boolean {
        return !Character.isWhitespace(c1)
    }

    @Throws(IOException::class)
    override fun incrementToken(): Boolean {
        typeAtt.setType(null)
        logger.trace("INCREMENT-TOKEN")
        var length = 0
        var start = -1
        var end = -1
        var bufferStart = position
        var continueTerm = false
        var startOffset = 0
        var endOffset = 0
        while (!tokenAtt.isState(TokenInfoAttribute.STATE_INPUT_FINISHED)) {
            if (entry == null) {
                while (true) {
                    if (position >= readLength) {
                        ////////////////////////////////////////////////////////////////////////////////
                        // 1. 원본 읽어오기 (버퍼 크기만큼 읽어옴)
                        ////////////////////////////////////////////////////////////////////////////////
                        val oldBuffer = backBuffer[0]
                        val newBuffer = backBuffer[1]
                        backBuffer[0] = newBuffer
                        backBuffer[1] = oldBuffer
                        baseOffset += readLength
                        readLength = input.read(newBuffer, 0, newBuffer.size)
                        logger.trace("READ {}/{}", newBuffer.size, readLength)
                        if (readLength > 0) {
                            buffer = newBuffer
                            tokenAtt.ref(newBuffer, 0, 0)
                            tokenAtt.rmState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED)
                            entry = null
                            tokenLength = readLength
                            while (tokenLength > 0) {
                                if (getType(newBuffer[tokenLength - 1].code) != WHITESPACE) {
                                    break
                                }
                                tokenLength--
                            }
                        } else {
                            readLength = 0
                            logger.trace("LENGTH:{} / {}", length, readLength)
                            if (length > 0) {
                                break
                            } else {
                                finalOffset = correctOffset(baseOffset)
                                logger.trace("TOKENIZER STOPPED!!")
                                tokenAtt.addState(TokenInfoAttribute.STATE_INPUT_FINISHED)
                                return false
                            }
                        }
                        if (tokenLength > 0 && tokenLength < FULL_TERM_LENGTH && baseOffset == 0) {
                            // FULL-TERM
                            tokenAtt.ref(newBuffer, 0, tokenLength)
                            tokenAtt.posTag(null)
                            offsetAtt.setOffset(0, tokenLength)
                            typeAtt.setType(FULL_STRING)
                            return true
                        }
                        position = 0
                        bufferStart = 0
                        chrCurrent = 0.toChar()
                        typeCurrent = null
                    }
                    ////////////////////////////////////////////////////////////////////////////////
                    // 2. 버퍼 내 단순 토크닝
                    ////////////////////////////////////////////////////////////////////////////////
                    val chrPrev = chrCurrent
                    val typePrev = typeCurrent
                    chrCurrent = buffer!![position]
                    typeCurrent = getType(chrCurrent.code)
                    position++
                    var pass = 1

                    if (typePrev == null) {
                        // nop
                    } else if (typePrev == WHITESPACE && typeCurrent != WHITESPACE) {
                        // nop
                    } else if (typePrev == WHITESPACE && typeCurrent == WHITESPACE) {
                        pass = 2
                    } else if (typePrev != WHITESPACE && typeCurrent == WHITESPACE) {
                        pass = 0
                    } else if (typePrev != typeCurrent) {
                        pass = 0
                    }

                    if (pass == 1) {
                        if (length == 0) {
                            assert(start == -1)
                            start = baseOffset + position - 1
                            end = start
                        }
                        end++
                        length++
                        if (position >= tokenLength) {
                            break
                        }
                    } else if (pass == 2) {
                        bufferStart = position
                        continue
                    } else if (length > 0) {
                        if (position >= tokenLength) {
                            position++
                        }
                        if (typePrev != WHITESPACE && typeCurrent == WHITESPACE) {
                            position--
                        } else if (typePrev != WHITESPACE && typeCurrent != WHITESPACE) {
                            position--
                        }
                        length = position - bufferStart
                        break
                    }
                }

                assert(start != -1)
                startOffset = correctOffset(start)
                endOffset = correctOffset(end)

                if (extractor != null) {
                    logger.trace("TOKEN:{} / {}~{} / {}", CharVector(buffer!!, bufferStart, length), position - bufferStart, length)
                    extLength = length
                    if (extLength > extractor!!.getTabularSize()) {
                        extLength = extractor!!.getTabularSize()
                        tabularFull = true
                    } else {
                        tabularFull = false
                    }
                    logger.trace("EXTRACT:{} / {}~{} / {}", CharVector(buffer!!, bufferStart, extLength), bufferStart, extLength, baseOffset)
                    extractor!!.setInput(buffer!!, bufferStart, extLength)
                    entry = extractor!!.extract()
                    continue
                } else {
                    tokenAtt.ref(buffer!!, bufferStart, length)
                    offsetAtt.setOffset(startOffset, endOffset.also { finalOffset = it })
                    logger.trace("TOKEN:{} / {}~{}", tokenAtt.ref(), startOffset, endOffset)
                }
            } else {
                while (entry != null) {
                    ////////////////////////////////////////////////////////////////////////////////
                    // 3. 한글분해
                    ////////////////////////////////////////////////////////////////////////////////
                    if (entry!!.column() <= 0) {
                        entry = entry!!.next()
                        continue
                    }
                    startOffset = correctOffset(baseOffset + entry!!.offset())
                    endOffset = correctOffset(baseOffset + entry!!.offset() + entry!!.column())
                    tokenAtt.ref(buffer!!, entry!!.offset(), entry!!.column())
                    tokenAtt.posTag(entry!!.posTag())
                    offsetAtt.setOffset(startOffset, endOffset)
                    logger.trace("TERM:{} / {}~{} / {} / {} / {}", tokenAtt.ref(), startOffset, endOffset, baseOffset, readLength, tokenAtt.posTag())
                    if (exportTerm) {
                        if (logger.isTraceEnabled) {
                            logger.trace("{} / {}~{}", String(buffer!!, entry!!.offset(), entry!!.column()), entry!!.offset(), entry!!.column())
                        }
                        termAtt.copyBuffer(buffer!!, entry!!.offset(), entry!!.column())
                    }
                    val extPosition0 = entry!!.offset() + entry!!.column()
                    var extPosition = extPosition0
                    val prevOffset = entry!!.offset()
                    entry = entry!!.next()
                    while (entry != null) {
                        if (entry!!.offset() < prevOffset) {
                            entry = entry!!.next()
                        } else {
                            break
                        }
                    }

                    if (entry == null) {
                        if (extPosition < position) {
                            if (tabularFull) {
                                logger.trace("CONTINUE-TERM:{}", tokenAtt.ref())
                                if (tokenAtt.ref()!!.length() != extractor!!.getTabularSize()) {
                                    extPosition -= tokenAtt.ref()!!.length()
                                    continueTerm = true
                                }
                            }
                            extLength = position - extPosition
                            if (extLength > extractor!!.getTabularSize()) {
                                extLength = extractor!!.getTabularSize()
                                tabularFull = true
                            } else {
                                tabularFull = false
                            }
                            logger.trace("EXTRACT:{} / {}~{} / {}", CharVector(buffer!!, extPosition, extLength), extPosition, extLength, baseOffset)
                            extractor!!.setInput(buffer!!, extPosition, extLength)
                            entry = extractor!!.extract()
                            if (continueTerm) {
                                continue
                            }
                        }
                    }
                    var ep = extPosition0
                    while (ep < tokenLength) {
                        if (getType(buffer!![ep].code) != WHITESPACE) { break }
                        ep++
                    }
                    if (ep == tokenLength) {
                        logger.trace("TOKENIZER BUFFER EXHAUSTED!")
                        tokenAtt.addState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED)
                        continue
                    }
                    break
                }
                logger.trace("OFFSET:{} / {} / {} / {}", startOffset, endOffset, position, baseOffset + readLength)
            }
            return true
        }
        return false
    }

    @Throws(IOException::class)
    override fun end() {
        logger.trace("TOKENIZER-END {}", finalOffset)
        super.end()
        offsetAtt.setOffset(finalOffset, finalOffset)
    }

    @Throws(IOException::class)
    override fun reset() {
        logger.trace("TOKENIZER-RESET")
        super.reset()
        position = 0
        extLength = 0
        baseOffset = 0
        readLength = 0
        finalOffset = 0
        tokenLength = 0
        chrCurrent = 0.toChar()
        typeCurrent = null
        tabularFull = false
    }

    @Throws(IOException::class)
    override fun close() {
        logger.trace("TOKENIZER-CLOSE")
        super.close()
    }

    companion object {
        @JvmStatic
        private val logger = LogManager.getLogger(ProductNameTokenizer::class.java)

        @JvmField val DEFAULT_MAX_WORD_LEN = 255
        @JvmField val IO_BUFFER_SIZE = 1000
        @JvmField val FULL_TERM_LENGTH = 64

        @JvmField val WHITESPACE = "<WHITESPACE>"
        @JvmField val SYMBOL = "<SYMBOL>"
        @JvmField val ALPHA = "<ALPHA>"
        @JvmField val NUMBER = "<NUMBER>"
        @JvmField val HANGUL = "<HANGUL>"
        @JvmField val HANGUL_JAMO = "<HANGUL_JAMO>"
        @JvmField val JAPANESE = "<JAPANESE>"
        @JvmField val CHINESE = "<CHINESE>"
        @JvmField val OTHER_LANGUAGE = "<OTHER_LANGUAGE>"
        @JvmField val UNCATEGORIZED = "<UNCATEGORIZED>"

        @JvmField val NUMBER_TRANS = "<NUMBER_TRANS>"
        @JvmField val MODEL_NAME = "<MODEL_NAME>"
        @JvmField val ALPHANUM = "<ALPHANUM>"
        @JvmField val ASCII = "<ASCII>"
        @JvmField val UNIT = "<UNIT>"
        @JvmField val UNIT_ALPHA = "<UNIT_ALPHA>"
        @JvmField val FULL_STRING = "<FULL_STRING>"
        @JvmField val MAKER = "<MAKER>"
        @JvmField val BRAND = "<BRAND>"
        @JvmField val COMPOUND = "<COMPOUND>"
        @JvmField val STOPWORD = "<STOPWORD>"

        @JvmField val MAX_UNIT_LENGTH = 10

        @JvmField val AVAIL_SYMBOLS = charArrayOf('-', '.', '/', '+', '&')
        @JvmField val AVAIL_SYMBOLS_STANDALONE = charArrayOf()
        @JvmField val AVAIL_SYMBOLS_CONNECTOR = charArrayOf('-', '.', '/', '&')

        @JvmField val SYMBOL_COLON = ':'

        @JvmField val PTN_NUMBER: Regex = Regex(
            "^(" +
                "(" +
                    "(" +
                        "([0-9]{0,3}([,][0-9]{3})*)" + "|" +
                        "([0-9]+)" +
                    ")" +
                    "([.][0-9]+)*" +
                ")" +
            ")" +
            "(" +
                "[:]" +
                "(" +
                    "(" +
                        "([0-9]{0,3}([,][0-9]{3})*)" + "|" +
                        "([0-9]+)" +
                    ")" +
                    "([.][0-9]+)*" +
                ")" +
            "){0,1}" +
            "$"
        )

        @JvmField val AVAIL_SYMBOLS_INNUMBER = charArrayOf(',', '.', SYMBOL_COLON)
        @JvmField val AVAIL_SYMBOLS_SPLIT = charArrayOf(',', '|', '[', ']', '<', '>', '{', '}', '^')

        @JvmStatic
        fun containsChar(array: CharArray, c: Char): Boolean {
            for (ch in array) {
                if (ch == c) {
                    return true
                }
            }
            return false
        }

        @JvmStatic
        fun containsChar(array: CharArray, buf: CharArray, length: Int): Boolean {
            for (ch in array) {
                if (!containsChar(array, ch)) {
                    return false
                }
            }
            return true
        }

        @JvmStatic
        fun isSplit(c: Char): String? {
            val ret = getType(c.code)
            if (ret == WHITESPACE || ret == SYMBOL) {
                return ret
            } else if (ret == SYMBOL && (containsChar(AVAIL_SYMBOLS_SPLIT, c) || (c.code > 128))) {
                return ret
            }
            return null
        }

        @JvmStatic
        fun getUniType(cv: CharSequence): String? {
            var ret: String? = null
            var prevType: String? = null
            var type: String? = null
            for (inx in 0 until cv.length) {
                prevType = type
                type = getType(cv[inx].code)
                if (prevType != null && type != prevType) {
                    if (prevType != type) {
                        type = UNCATEGORIZED
                        break
                    }
                }
            }
            ret = type
            return ret
        }

        @JvmStatic
        fun isAlphaNum(cv: CharVector): Boolean {
            var ret = true
            if (cv.length() == 0) {
                return false
            }
            for (inx in 0 until cv.length()) {
                val type = getType(cv.array()[cv.offset() + inx].code)
                if (!(type == ALPHA || type == NUMBER)) {
                    ret = false
                    break
                }
            }
            return ret
        }

        @JvmStatic
        fun getTermType(cv: CharSequence): String? {
            var ret: String? = null
            var prevType: String? = null
            var type: String? = null
            for (inx in 0 until cv.length) {
                prevType = type
                type = getType(cv[inx].code)
                if (prevType != null && type != prevType) {
                    type = if ((prevType == ALPHA && type == NUMBER) || (prevType == NUMBER && type == ALPHA)) {
                        ALPHANUM
                    } else if (prevType == ALPHANUM && (type == ALPHA || type == NUMBER)) {
                        ALPHANUM
                    } else if ((prevType == ALPHA && type == SYMBOL) || (prevType == NUMBER && type == SYMBOL)
                        || (prevType == ALPHANUM && type == SYMBOL)) {
                        ASCII
                    } else if (prevType == ASCII && (type == ALPHA || type == NUMBER || type == SYMBOL)) {
                        ASCII
                    } else {
                        UNCATEGORIZED
                    }
                }
            }
            ret = type
            return ret
        }

        @JvmStatic
        fun getType(ch: Int): String {
            if (Character.isWhitespace(ch)) {
                return WHITESPACE
            }

            val type = Character.getType(ch)

            when (type) {
                Character.DASH_PUNCTUATION.toInt(),
                Character.START_PUNCTUATION.toInt(),
                Character.END_PUNCTUATION.toInt(),
                Character.CONNECTOR_PUNCTUATION.toInt(),
                Character.OTHER_PUNCTUATION.toInt(),
                Character.MATH_SYMBOL.toInt(),
                Character.CURRENCY_SYMBOL.toInt(),
                Character.MODIFIER_SYMBOL.toInt(),
                Character.OTHER_SYMBOL.toInt(),
                Character.INITIAL_QUOTE_PUNCTUATION.toInt(),
                Character.FINAL_QUOTE_PUNCTUATION.toInt() -> return SYMBOL

                Character.OTHER_LETTER.toInt() -> {
                    val unicodeBlock = Character.UnicodeBlock.of(ch)
                    return when (unicodeBlock) {
                        Character.UnicodeBlock.HANGUL_SYLLABLES -> HANGUL
                        Character.UnicodeBlock.HANGUL_COMPATIBILITY_JAMO -> HANGUL_JAMO
                        Character.UnicodeBlock.HIRAGANA, Character.UnicodeBlock.KATAKANA -> JAPANESE
                        Character.UnicodeBlock.CJK_UNIFIED_IDEOGRAPHS -> CHINESE
                        else -> OTHER_LANGUAGE
                    }
                }

                Character.UPPERCASE_LETTER.toInt(),
                Character.LOWERCASE_LETTER.toInt() -> return ALPHA

                Character.DECIMAL_DIGIT_NUMBER.toInt() -> return NUMBER
            }

            return UNCATEGORIZED
        }
    }
}

