110→                    parsingRule!!.processRule(termList, true)
111→                }
112→                logger.trace("ENTRY QUEUE-SIZE:{}", termList.size)
113→            } else {
114→                var entry: RuleEntry? = null
115→                while (termList[0].also { entry = it } == null) {
116→                    termList.removeAt(0)
117→                }
118→
119→                var subEntryList = entry!!.subEntry
120→                var synonyms = entry!!.synonym
121→                logger.trace("SUB:{} / {} / {}", entry, synonyms, subEntryList)
122→
123→                if (option!!.useForQuery()) {
