140→                    applySynonym(token!!, entry!!)
141→                    if (entry!!.subEntry != null && entry!!.subEntry.size > 0) {
142→                        for (subEntry in entry!!.subEntry) {
143→                            var synonymList: List<CharSequence>? = null
144→                            val cv = subEntry.makeTerm(null)
145→                            testEntry(subEntry, null)
146→                            if (option!!.useSynonym() && synonymDictionary!!.containsKey(cv)) {
147→                                val synArray = synonymDictionary!!.get(cv)
148→                                if (synArray != null) {
