169→                    if (entry!!.buf != null) {
170→                        logger.trace("TERMLIST:{}", termList)
171→                        logger.trace("SUB:{}", entry!!.subEntry)
172→                        logger.trace("SYN:{}{}", "", entry!!.synonym)
173→                        testEntry(entry!!, null)
174→                        token = applyEntry(entry!!)
175→                        subEntryList = entry!!.subEntry
176→                        if (synonyms != null) {
177→                            if (subEntryList == null) {
178→                                subEntryList = ArrayList()
179→                                entry!!.subEntry = subEntryList
180→                            }
181→                            for (sinx in synonyms.indices) {
182→                                val cv = CharVector(synonyms[sinx])
