238→    private fun applySynonym(token: CharVector, entry: RuleEntry) {
239→        val synonyms: MutableList<CharSequence> = ArrayList()
240→        if (option!!.useSynonym() && option!!.useForQuery()) {
241→            if (synonymDictionary != null && synonymDictionary!!.containsKey(token)) {
242→                val wordSynonym = synonymDictionary!!.get(token)
243→                logger.trace("SYNONYM-FOUND:{}{}", "", wordSynonym)
244→                if (wordSynonym != null) {
245→                    synonyms.addAll(Arrays.asList(*wordSynonym))
246→                }
247→                if (typeAttribute.type() != UNIT) {
248→                    val synonymsExt = synonymExtract(synonyms, entry)
249→                    if (synonymsExt != null) {
250→                        return applySynonymFinish(synonymsExt, entry)
251→                    }
252→                }
253→            }
254→        }
255→        if (entry.synonym != null && option!!.useSynonym()) {
256→            synonyms.addAll(Arrays.asList(*entry.synonym!!))
257→        }
258→        if (synonyms.size > 0) {
259→            logger.trace("SET-SYNONYM:{}", synonyms)
260→            synonymAttribute.setSynonyms(synonyms)
261→        }
262→    }
