264→    private fun applySynonymFinish(synonyms: List<CharSequence>, entry: RuleEntry) {
265→        val result: MutableList<CharSequence> = ArrayList(synonyms)
266→        if (entry.synonym != null && option!!.useSynonym()) {
267→            result.addAll(Arrays.asList(*entry.synonym!!))
268→        }
269→        if (result.size > 0) {
270→            logger.trace("SET-SYNONYM:{}", result)
271→            synonymAttribute.setSynonyms(result)
272→        }
273→    }
