275→    fun synonymExtract(synonyms: List<CharSequence>, entry: RuleEntry): List<CharSequence>? {
276→        val parsingRule = this.parsingRule!!.clone()
277→        parsingRule.option = AnalyzerOption()
278→        parsingRule.option!!.useSynonym(false)
279→        parsingRule.option!!.useStopword(true)
280→        val entryList: MutableList<RuleEntry> = ArrayList()
281→
282→        var result: MutableList<CharSequence>? = null
283→        val dupSet: MutableSet<String> = HashSet()
284→        for (synonymInx in synonyms.indices) {
285→            val synonym = CharVector.valueOf(synonyms[synonymInx])
286→            logger.trace("synonym:{}", synonym)
287→
288→            val synonymTokens: MutableList<CharVector> = ArrayList(1)
289→            if (synonym is CharVector) {
290→                if (synonym.hasWhitespaces()) {
291→                    val terms = synonym.splitByWhitespace()
292→                    for (term in terms) {
293→                        if (term.length() > 0) {
294→                            synonymTokens.add(term)
295→                        }
296→                    }
297→                } else {
298→                    synonymTokens.add(synonym)
299→                }
300→            }
301→
302→            val sb = StringBuilder()
303→            for (synonymCV in synonymTokens) {
304→                logger.trace("TRACING SYNONYM : {}", synonymCV)
305→                extractor!!.setInput(synonymCV.array(), synonymCV.offset(), synonymCV.length())
306→                var cvEntry: KoreanWordExtractor.ExtractedEntry? = extractor!!.extract()
307→                while (cvEntry != null) {
308→                    val cv = synonymCV.clone()
309→                    cv.offset(cvEntry!!.offset())
310→                    cv.length(cvEntry!!.column())
311→                    if (cv.length() < synonymCV.length()) {
312→                        val trimmed = cv.trim()
313→                        if (trimmed.length() > 0) {
314→                            Entry.addEntry(entryList, trimmed, getTermType(trimmed), cvEntry!!.posTag(),
315→                                entry.startOffset, entry.endOffset, spaceDictionary)
316→                        }
317→                    } else {
318→                        Entry.addEntry(entryList, synonymCV, getTermType(synonymCV), cvEntry!!.posTag(),
319→                            entry.startOffset, entry.endOffset, spaceDictionary)
320→                        break
321→                    }
322→                    cvEntry = cvEntry!!.next()
323→                }
324→
325→                if (entryList.size > 0) {
326→                    logger.trace("SYNONYM-QUEUE:{}", entryList)
327→                    parsingRule.processRule(entryList, false)
328→                    val tokenCV = CharVector()
329→                    while (entryList.size > 0) {
330→                        entryList.removeAt(0).makeTerm(tokenCV)
331→                        if (sb.isNotEmpty()) {
332→                            sb.append(" ")
333→                        }
334→                        sb.append(tokenCV.toString())
335→                    }
336→                }
337→            }
338→
339→            if (sb.isNotEmpty()) {
340→                val idString = sb.toString()
341→                if (!dupSet.contains(idString)) {
342→                    if (result == null) {
343→                        result = ArrayList()
344→                    }
345→                    result.add(idString)
346→                    logger.trace("synonym:{}", idString)
347→                    dupSet.add(idString)
348→                }
349→            }
350→        }
351→        return result
352→    }
