354→    fun testEntry(entry: RuleEntry, parent: RuleEntry?) {
355→        if ((parent == null || parent.type == MODEL_NAME) && entry.type == NUMBER && entry.length >= 5) {
356→            entry.type = MODEL_NAME
357→        } else if (entry.type == UNIT_ALPHA) {
358→            entry.type = UNIT
359→        } else if (entry.type == NUMBER_TRANS) {
360→            entry.type = NUMBER
361→            val entryStr = CharVector(entry.makeTerm(null).toString().replace(",", ""))
362→            if (entryStr.length() != entry.length) {
363→                if (option!!.useForQuery()) {
364→                    if (entry.length != entryStr.length()) {
365→                        extraTermAttribute.addExtraTerm(entryStr.toString(), NUMBER, null as List<CharSequence>?)
366→                    }
367→                } else if (parent != null) {
368→                    var subEntryList = parent.subEntry
369→                    if (subEntryList == null) {
370→                        subEntryList = ArrayList()
371→                        parent.subEntry = subEntryList
372→                    }
373→                    if (subEntryList[0] === entry) {
374→                        subEntryList.add(1, RuleEntry(entryStr.array(), entryStr.offset(), entryStr.length(),
375→                            entry.startOffset, entry.endOffset, entry.type))
376→                    }
377→                } else {
378→                    var subEntryList = entry.subEntry
379→                    if (subEntryList == null) {
380→                        subEntryList = ArrayList()
381→                        entry.subEntry = subEntryList
382→                    }
383→                    subEntryList.add(RuleEntry(entryStr.array(), entryStr.offset(), entryStr.length(),
384→                        entry.startOffset, entry.endOffset, entry.type))
385→                }
386→            }
387→        } else if (entry.type == null) {
388→            entry.type = UNCATEGORIZED
389→        }
390→    }
391→
392→    private fun applyEntry(entry: RuleEntry): CharVector {
