package com.danawa.search.analysis.product

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.dict.SetDictionary
import com.danawa.search.analysis.dict.SpaceDictionary
import com.danawa.search.analysis.dict.SynonymDictionary
import com.danawa.search.analysis.korean.KoreanWordExtractor
import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag
import com.danawa.search.analysis.product.rule.Entry
import com.danawa.search.analysis.product.rule.RuleEntry
import com.danawa.util.CharVector

import org.apache.logging.log4j.LogManager
import org.apache.lucene.analysis.tokenattributes.ExtraTermAttribute
import org.apache.lucene.analysis.tokenattributes.CharTermAttribute
import org.apache.lucene.analysis.tokenattributes.OffsetAttribute
import org.apache.lucene.analysis.tokenattributes.PositionIncrementAttribute
import org.apache.lucene.analysis.tokenattributes.SynonymAttribute
import org.apache.lucene.analysis.tokenattributes.TokenInfoAttribute
import org.apache.lucene.analysis.tokenattributes.TypeAttribute
import org.apache.lucene.analysis.TokenFilter
import org.apache.lucene.analysis.TokenStream

import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.FULL_STRING
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.MODEL_NAME
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.NUMBER
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.NUMBER_TRANS
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.STOPWORD
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.UNCATEGORIZED
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.UNIT
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.UNIT_ALPHA
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.getTermType

import java.io.IOException
import java.util.*

class ProductNameAnalysisFilter : TokenFilter {

    private val termAttribute = addAttribute(CharTermAttribute::class.java)
    private val tokenAttribute = addAttribute(TokenInfoAttribute::class.java)
    private val offsetAttribute = addAttribute(OffsetAttribute::class.java)
    private val extraTermAttribute = addAttribute(ExtraTermAttribute::class.java)
    private val synonymAttribute = addAttribute(SynonymAttribute::class.java)
    private val typeAttribute = addAttribute(TypeAttribute::class.java)
    private val posIncrAtt = addAttribute(PositionIncrementAttribute::class.java)
    private var option: AnalyzerOption? = null

    private var extractor: KoreanWordExtractor? = null

    private var synonymDictionary: SynonymDictionary? = null
    private var spaceDictionary: SpaceDictionary? = null
    private var stopDictionary: SetDictionary? = null
    private var dictionary: ProductNameDictionary? = null

    private var parsingRule: ProductNameParsingRule? = null
    private var token: CharVector? = null
    private var termList: MutableList<RuleEntry>

    private var positionIncrement = 0

    constructor(input: TokenStream) : super(input) {
        termList = ArrayList()
    }

    constructor(input: TokenStream, dictionary: ProductNameDictionary?, option: AnalyzerOption?) : super(input) {
        if (dictionary != null) {
            this.dictionary = dictionary
            this.synonymDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary::class.java)
            this.spaceDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_SPACE, SpaceDictionary::class.java)
            this.stopDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_STOP, SetDictionary::class.java)
        }
        this.extractor = KoreanWordExtractor(dictionary!!)
        this.option = option
        extraTermAttribute.init(this)
        termList = ArrayList()
        super.clearAttributes()
        logger.trace("init")
    }

    @Throws(IOException::class)
    override fun incrementToken(): Boolean {
        var ret = false
        if (parsingRule == null) {
            parsingRule = ProductNameParsingRule(extractor, dictionary, option)
        }
        synonymAttribute.setSynonyms(null)
        extraTermAttribute.init(this)

        while (true) {
            if (termList.size == 0) {
                if (tokenAttribute.isState(TokenInfoAttribute.STATE_INPUT_FINISHED)) {
                    ret = false
                    break
                }
                while (input.incrementToken()) {
                    val ref = tokenAttribute.ref()
                    val type = typeAttribute.type()
                    val posTag = tokenAttribute.posTag()

                    if (!(option!!.useForQuery() && option!!.useFullString()) && FULL_STRING == type) {
                        continue
                    }
                    Entry.addEntry(termList, ref!!, type, posTag,
                        offsetAttribute.startOffset(), offsetAttribute.endOffset(), spaceDictionary)
                    if (tokenAttribute.isState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED)) {
                        break
                    }
                }
                if (termList.size > 0) {
                    parsingRule!!.processRule(termList, true)
                }
                logger.trace("ENTRY QUEUE-SIZE:{}", termList.size)
            } else {
                var entry: RuleEntry? = null
                while (termList[0].also { entry = it } == null) {
                    termList.removeAt(0)
                }

                var subEntryList = entry!!.subEntry
                var synonyms = entry!!.synonym
                logger.trace("SUB:{} / {} / {}", entry, synonyms, subEntryList)

                if (option!!.useForQuery()) {
                    // 질의용
                    if (subEntryList != null) {
                        if (entry!!.type == UNIT || entry!!.type == UNIT_ALPHA) {
                            var sinx = 0
                            while (sinx < subEntryList.size) {
                                if (subEntryList[sinx].type == NUMBER ||
                                    subEntryList[sinx].type == NUMBER_TRANS) {
                                    subEntryList.removeAt(sinx)
                                    sinx--
                                }
                                sinx++
                            }
                        }
                    }
                    testEntry(entry!!, null)
                    token = applyEntry(entry!!)
                    applySynonym(token!!, entry!!)
                    if (entry!!.subEntry != null && entry!!.subEntry.size > 0) {
                        for (subEntry in entry!!.subEntry) {
                            var synonymList: List<CharSequence>? = null
                            val cv = subEntry.makeTerm(null)
                            testEntry(subEntry, null)
                            if (option!!.useSynonym() && synonymDictionary!!.containsKey(cv)) {
                                val synArray = synonymDictionary!!.get(cv)
                                if (synArray != null) {
                                    synonymList = Arrays.asList(*synArray)
                                }
                                logger.trace("token:{} / synonym:{}", cv, synonymList)
                            }
                            extraTermAttribute.addExtraTerm(cv.toString(), subEntry.type!!, synonymList)
                        }
                    }
                    termList.removeAt(0)
                    if (tokenAttribute.isState(TokenInfoAttribute.STATE_TERM_STOP)) {
                        logger.trace("STOP WORD:{}", token)
                        typeAttribute.setType(STOPWORD)
                        if (option!!.useStopword()) {
                            continue
                        }
                    }
                    ret = true
                    positionIncrement = 1
                    break
                } else {
                    // 색인용
                    if (entry!!.buf != null) {
                        logger.trace("TERMLIST:{}", termList)
                        logger.trace("SUB:{}", entry!!.subEntry)
                        logger.trace("SYN:{}{}", "", entry!!.synonym)
                        testEntry(entry!!, null)
                        token = applyEntry(entry!!)
                        subEntryList = entry!!.subEntry
                        if (synonyms != null) {
                            if (subEntryList == null) {
                                subEntryList = ArrayList()
                                entry!!.subEntry = subEntryList
                            }
                            for (sinx in synonyms.indices) {
                                val cv = CharVector(synonyms[sinx])
                                subEntryList.add(sinx, RuleEntry(cv.array(), 0, cv.length(),
                                    entry!!.startOffset, entry!!.endOffset, entry!!.type))
                            }
                            entry!!.synonym = null
                            synonyms = null
                        }
                        if (subEntryList == null) {
                            termList.removeAt(0)
                        } else {
                            entry!!.buf = CharArray(0)
                        }
                        if (tokenAttribute.isState(TokenInfoAttribute.STATE_TERM_STOP)) {
                            logger.trace("STOP WORD:{}", token)
                            typeAttribute.setType(STOPWORD)
                            if (option!!.useStopword()) {
                                continue
                            }
                        }
                        ret = true
                        positionIncrement = 1
                        break
                    } else if (subEntryList.size > 0) {
                        val subEntry = subEntryList[0]
                        testEntry(subEntry, entry)
                        token = applyEntry(subEntry)
                        subEntryList.removeAt(0)
                        if (tokenAttribute.isState(TokenInfoAttribute.STATE_TERM_STOP)) {
                            logger.trace("STOP WORD:{}", token)
                            typeAttribute.setType(STOPWORD)
                            if (option!!.useStopword()) {
                                continue
                            }
                        }
                        ret = true
                        positionIncrement = 0
                        break
                    } else if (subEntryList.size == 0) {
                        termList.removeAt(0)
                    }
                }
            }
        }

        posIncrAtt.setPositionIncrement(positionIncrement)

        if (logger.isTraceEnabled) {
            if (ret) {
                logger.trace("TERM:{} / {}~{} / {} ", termAttribute, offsetAttribute.startOffset(), offsetAttribute.endOffset())
            } else {
                logger.trace("FILTER STOPPED!!")
            }
        }
        return ret
    }

    private fun applySynonym(token: CharVector, entry: RuleEntry) {
        val synonyms: MutableList<CharSequence> = ArrayList()
        if (option!!.useSynonym() && option!!.useForQuery()) {
            if (synonymDictionary != null && synonymDictionary!!.containsKey(token)) {
                val wordSynonym = synonymDictionary!!.get(token)
                logger.trace("SYNONYM-FOUND:{}{}", "", wordSynonym)
                if (wordSynonym != null) {
                    synonyms.addAll(Arrays.asList(*wordSynonym))
                }
                if (typeAttribute.type() != UNIT) {
                    val synonymsExt = synonymExtract(synonyms, entry)
                    if (synonymsExt != null) {
                        return applySynonymFinish(synonymsExt, entry)
                    }
                }
            }
        }
        if (entry.synonym != null && option!!.useSynonym()) {
            synonyms.addAll(Arrays.asList(*entry.synonym!!))
        }
        if (synonyms.size > 0) {
            logger.trace("SET-SYNONYM:{}", synonyms)
            synonymAttribute.setSynonyms(synonyms)
        }
    }

    private fun applySynonymFinish(synonyms: List<CharSequence>, entry: RuleEntry) {
        val result: MutableList<CharSequence> = ArrayList(synonyms)
        if (entry.synonym != null && option!!.useSynonym()) {
            result.addAll(Arrays.asList(*entry.synonym!!))
        }
        if (result.size > 0) {
            logger.trace("SET-SYNONYM:{}", result)
            synonymAttribute.setSynonyms(result)
        }
    }

    fun synonymExtract(synonyms: List<CharSequence>, entry: RuleEntry): List<CharSequence>? {
        val parsingRule = this.parsingRule!!.clone()
        parsingRule.option = AnalyzerOption()
        parsingRule.option!!.useSynonym(false)
        parsingRule.option!!.useStopword(true)
        val entryList: MutableList<RuleEntry> = ArrayList()

        var result: MutableList<CharSequence>? = null
        val dupSet: MutableSet<String> = HashSet()
        for (synonymInx in synonyms.indices) {
            val synonym = CharVector.valueOf(synonyms[synonymInx])
            logger.trace("synonym:{}", synonym)

            val synonymTokens: MutableList<CharVector> = ArrayList(1)
            if (synonym is CharVector) {
                if (synonym.hasWhitespaces()) {
                    val terms = synonym.splitByWhitespace()
                    for (term in terms) {
                        if (term.length() > 0) {
                            synonymTokens.add(term)
                        }
                    }
                } else {
                    synonymTokens.add(synonym)
                }
            }

            val sb = StringBuilder()
            for (synonymCV in synonymTokens) {
                logger.trace("TRACING SYNONYM : {}", synonymCV)
                extractor!!.setInput(synonymCV.array(), synonymCV.offset(), synonymCV.length())
                var cvEntry: KoreanWordExtractor.ExtractedEntry? = extractor!!.extract()
                while (cvEntry != null) {
                    val cv = synonymCV.clone()
                    cv.offset(cvEntry!!.offset())
                    cv.length(cvEntry!!.column())
                    if (cv.length() < synonymCV.length()) {
                        val trimmed = cv.trim()
                        if (trimmed.length() > 0) {
                            Entry.addEntry(entryList, trimmed, getTermType(trimmed), cvEntry!!.posTag(),
                                entry.startOffset, entry.endOffset, spaceDictionary)
                        }
                    } else {
                        Entry.addEntry(entryList, synonymCV, getTermType(synonymCV), cvEntry!!.posTag(),
                            entry.startOffset, entry.endOffset, spaceDictionary)
                        break
                    }
                    cvEntry = cvEntry!!.next()
                }

                if (entryList.size > 0) {
                    logger.trace("SYNONYM-QUEUE:{}", entryList)
                    parsingRule.processRule(entryList, false)
                    val tokenCV = CharVector()
                    while (entryList.size > 0) {
                        entryList.removeAt(0).makeTerm(tokenCV)
                        if (sb.isNotEmpty()) {
                            sb.append(" ")
                        }
                        sb.append(tokenCV.toString())
                    }
                }
            }

            if (sb.isNotEmpty()) {
                val idString = sb.toString()
                if (!dupSet.contains(idString)) {
                    if (result == null) {
                        result = ArrayList()
                    }
                    result.add(idString)
                    logger.trace("synonym:{}", idString)
                    dupSet.add(idString)
                }
            }
        }
        return result
    }

    fun testEntry(entry: RuleEntry, parent: RuleEntry?) {
        if ((parent == null || parent.type == MODEL_NAME) && entry.type == NUMBER && entry.length >= 5) {
            entry.type = MODEL_NAME
        } else if (entry.type == UNIT_ALPHA) {
            entry.type = UNIT
        } else if (entry.type == NUMBER_TRANS) {
            entry.type = NUMBER
            val entryStr = CharVector(entry.makeTerm(null).toString().replace(",", ""))
            if (entryStr.length() != entry.length) {
                if (option!!.useForQuery()) {
                    if (entry.length != entryStr.length()) {
                        extraTermAttribute.addExtraTerm(entryStr.toString(), NUMBER, null as List<CharSequence>?)
                    }
                } else if (parent != null) {
                    var subEntryList = parent.subEntry
                    if (subEntryList == null) {
                        subEntryList = ArrayList()
                        parent.subEntry = subEntryList
                    }
                    if (subEntryList[0] === entry) {
                        subEntryList.add(1, RuleEntry(entryStr.array(), entryStr.offset(), entryStr.length(),
                            entry.startOffset, entry.endOffset, entry.type))
                    }
                } else {
                    var subEntryList = entry.subEntry
                    if (subEntryList == null) {
                        subEntryList = ArrayList()
                        entry.subEntry = subEntryList
                    }
                    subEntryList.add(RuleEntry(entryStr.array(), entryStr.offset(), entryStr.length(),
                        entry.startOffset, entry.endOffset, entry.type))
                }
            }
        } else if (entry.type == null) {
            entry.type = UNCATEGORIZED
        }
    }

    private fun applyEntry(entry: RuleEntry): CharVector {
        termAttribute.copyBuffer(entry.buf, entry.start, entry.length)
        offsetAttribute.setOffset(entry.startOffset, entry.endOffset)
        typeAttribute.setType(entry.type)
        if (option!!.toUppercase()) {
            toUppercase(termAttribute.buffer())
        }
        token = entry.makeTerm(null)
        if (stopDictionary != null && stopDictionary!!.set().contains(token as CharSequence)) {
            tokenAttribute.addState(TokenInfoAttribute.STATE_TERM_STOP)
        } else {
            tokenAttribute.rmState(TokenInfoAttribute.STATE_TERM_STOP)
        }
        return entry.makeTerm(null)
    }

    @Throws(IOException::class)
    override fun reset() {
        super.reset()
        extraTermAttribute.init(this)
        parsingRule = null
        token = null
        termList = ArrayList()
        this.clearAttributes()
    }

    fun toUppercase(buffer: CharArray) {
        for (inx in buffer.indices) {
            buffer[inx] = Character.toUpperCase(buffer[inx])
        }
    }

    companion object {
        @JvmStatic
        private val logger = LogManager.getLogger(ProductNameAnalysisFilter::class.java)
    }
}

