package com.danawa.search.analysis.korean

class MorphUtil {
    companion object {
        private val CHOSEONG = charArrayOf(
            'ㄱ', 'ㄲ', 'ㄴ', 'ㄷ', 'ㄸ', 'ㄹ', 'ㅁ', 'ㅂ', 'ㅃ', 'ㅅ', 'ㅆ', 'ㅇ', 'ㅈ', 'ㅉ', 'ㅊ',
            'ㅋ', 'ㅌ', 'ㅍ', 'ㅎ'
        )

        private val JUNGSEONG = charArrayOf(
            'ㅏ', 'ㅐ', 'ㅑ', 'ㅒ', 'ㅓ', 'ㅔ', 'ㅕ', 'ㅖ', 'ㅗ', 'ㅘ', 'ㅙ', 'ㅚ', 'ㅛ', 'ㅜ', 'ㅝ',
            'ㅞ', 'ㅟ', 'ㅠ', 'ㅡ', 'ㅢ', 'ㅣ'
        )

        private val JONGSEONG = charArrayOf(
            '\u0000', 'ㄱ', 'ㄲ', 'ㄳ', 'ㄴ', 'ㄵ', 'ㄶ', 'ㄷ', 'ㄹ', 'ㄺ', 'ㄻ', 'ㄼ', 'ㄽ', 'ㄾ',
            'ㄿ', 'ㅀ', 'ㅁ', 'ㅂ', 'ㅄ', 'ㅅ', 'ㅆ', 'ㅇ', 'ㅈ', 'ㅊ', 'ㅋ', 'ㅌ', 'ㅍ', 'ㅎ'
        )

        private const val JUNG_JONG_LENGTH = 21 * 28
        private const val JONG_LENGTH = 28

        private fun getCHOSEONGIDX(ch: Char): Int {
            for (i in CHOSEONG.indices) {
                if (ch == CHOSEONG[i]) return i
            }
            return -1
        }

        private fun getJUNGSEONGIDX(ch: Char): Int {
            for (i in JUNGSEONG.indices) {
                if (ch == JUNGSEONG[i]) return i
            }
            return -1
        }

        private fun getJONGSEONGIDX(ch: Char): Int {
            for (i in JONGSEONG.indices) {
                if (ch == JONGSEONG[i]) return i
            }
            return -1
        }

        @JvmStatic
        fun makeChar(ch: Char, mdl: Int, last: Int): Char {
            val c = ch - 0xAC00.toChar()
            val first = c / JUNG_JONG_LENGTH
            return compound(first, mdl, last)
        }

        @JvmStatic
        fun compound(first: Int, middle: Int, last: Int): Char {
            return (0xAC00 + first * JUNG_JONG_LENGTH + middle * JONG_LENGTH + last).toChar()
        }

        @JvmStatic
        fun getFirstElement(c: Char): Char {
            if (!isHangul(c)) return c
            return CHOSEONG[(c - 0xAC00.toChar()) / JUNG_JONG_LENGTH]
        }

        @JvmStatic
        fun getMiddleElement(c: Char): Char {
            if (!isHangul(c)) return c
            val v = (c - 0xAC00.toChar()) % JUNG_JONG_LENGTH
            return JUNGSEONG[v / JONG_LENGTH]
        }

        @JvmStatic
        fun hasLastElement(c: Char): Boolean = getLastElementCode(c) > 0

        @JvmStatic
        fun getLastElementCode(c: Char): Int {
            if (!isHangul(c)) return -1
            return (c - 0xAC00.toChar()) % 28
        }

        @JvmStatic
        fun isHangul(c: Char): Boolean {
            if (c.code < 0xAC00 || c.code > 0xD7A3) return false
            return true
        }

        @JvmStatic
        fun split(c: Char): IntArray {
            val sub = IntArray(3)
            val v = c - 0xAC00.toChar()
            sub[0] = v / JUNG_JONG_LENGTH
            sub[1] = (v % JUNG_JONG_LENGTH) / JONG_LENGTH
            sub[2] = v % JONG_LENGTH
            return sub
        }

        @JvmStatic
        fun combine(vararg chars: Char): Char {
            return when {
                chars.size > 2 -> compound(getCHOSEONGIDX(chars[0]), getJUNGSEONGIDX(chars[1]), getJONGSEONGIDX(chars[2]))
                chars.size > 1 -> compound(getCHOSEONGIDX(chars[0]), getJUNGSEONGIDX(chars[1]), 0)
                chars.size == 1 -> chars[0]
                else -> 0.toChar()
            }
        }

        @JvmStatic
        fun decompose(c: Char): CharArray {
            if (!isHangul(c)) return charArrayOf(c)
            val v = c - 0xAC00.toChar()
            val choseong = CHOSEONG[v / JUNG_JONG_LENGTH]
            val remainder = v % JUNG_JONG_LENGTH
            val jungseong = JUNGSEONG[remainder / JONG_LENGTH]
            val jongseong = JONGSEONG[remainder % JONG_LENGTH]
            return if (jongseong.code != 0) {
                charArrayOf(choseong, jungseong, jongseong)
            } else {
                charArrayOf(choseong, jungseong)
            }
        }
    }
}

