146→                try {
147→                    if (tries == 0) {
148→                        baseFile = ResourceResolver.getResourceRoot(ProductNameDictionary::class.java)
149→                    } else {
150→                        baseFile = env.configDir().toFile()
151→                    }
152→                    logger.debug("TESTING PRODUCT DICTIONARY BASE : {}", baseFile!!.absolutePath)
153→                    if (baseFile != null && baseFile!!.exists()) {
154→                        logger.debug("PRODUCT DICTIONARY BASE : {}", baseFile!!.absolutePath)
155→                    }
156→                } catch (e: Exception) {
157→                    logger.error("", e)
158→                    baseFile = null
159→                    configFile = null
160→                    continue
161→                }
162→                configFile = File(baseFile, ANALYSIS_PROP)
163→                if (configFile!!.exists()) {
164→                    logger.debug("DICTIONARY PROPERTIES : {}", configFile!!.absolutePath)
165→                    break
166→                } else {
167→                    baseFile = null
168→                    configFile = null
169→                }
170→            }
171→            val dictProp = ResourceResolver.readYmlConfig(configFile!!)
172→            if (dictProp == null) {
173→                logger.error("DICTIONARY PROPERTIES FILE NOT FOUND {}", configFile!!.absolutePath)
174→            }
175→            return loadDictionary(baseFile!!, dictProp!!)
