366→        @JvmStatic
367→        fun compileDictionaryOne(repo: DictionaryRepository, dictList: JSONArray, dictionaryId: String): MutableMap<String, Any?>? {
368→            val result = HashMap<String, Any?>()
369→
370→            for (inx in 0 until dictList.length()) {
371→                val row = dictList.optJSONObject(inx)
372→                val dictId = row.optString(ATTR_DICTIONARY_NAME)
373→                if (dictionaryId != dictId) {
374→                    continue
375→                }
376→                val type = getType(row)
377→                val tokenType = getTokenType(row)
378→                val label = getLabel(row)
379→                val seq = getSeq(row)
380→                val ignoreCase = row.optBoolean(ATTR_DICTIONARY_IGNORECASE, true)
381→
382→                val source = repo.getSource(dictionaryId)
383→
384→                var sourceDictionary: SourceDictionary<*>? = when (type) {
385→                    Type.SET -> SetDictionary(ignoreCase)
386→                    Type.MAP -> MapDictionary(ignoreCase)
387→                    Type.SYNONYM, Type.SYNONYM_2WAY -> SynonymDictionary(ignoreCase)
388→                    Type.SPACE -> SpaceDictionary(ignoreCase)
389→                    Type.CUSTOM -> CustomDictionary(ignoreCase)
390→                    Type.INVERT_MAP -> InvertMapDictionary(ignoreCase)
391→                    Type.COMPOUND -> CompoundDictionary(ignoreCase)
392→                    else -> null
393→                }
394→
395→                if (sourceDictionary != null) {
396→                    var cnt = 0
397→                    while (source.hasNext()) {
398→                        val data = source.next()
399→                        var id = ""
400→                        var keyword = ""
401→                        var value = ""
402→                        var line: String
403→                        if (data[0] != null) { id = data[0].toString().trim { it <= ' ' } }
404→                        if (data[1] != null) { keyword = data[1].toString().trim { it <= ' ' } }
405→                        if (data[2] != null) { value = data[2].toString().trim { it <= ' ' } }
406→                        line = when {
407→                            type == Type.SYNONYM || type == Type.SYNONYM_2WAY -> {
408→                                if (keyword.isNotEmpty()) "$keyword\t$value" else value
409→                            }
410→                            type == Type.CUSTOM -> {
411→                                if (id.isNotEmpty()) "$keyword\t$id" else keyword
412→                            }
413→                            else -> {
414→                                if (value.isNotEmpty()) "$keyword\t$value" else keyword
415→                            }
416→                        }
417→                        sourceDictionary.addSourceLineEntry(line)
418→                        cnt++
419→                    }
420→                    result["cnt"] = cnt
421→                    logger.info("DICTIONARY LOADED! [{}] / {} / {} / {}", cnt, dictionaryId, type, tokenType)
422→                }
423→                result["dict"] = sourceDictionary
424→                result["type"] = dictId
425→                result["id"] = dictId
426→                return result
427→            }
428→            return null
429→        }
