469→        fun getTwowaySynonymWord(mainWord: CharSequence, synonymMap: Map<CharSequence, Array<CharSequence>>): List<CharSequence>? {
470→            val map = HashMap<CharSequence, MutableList<CharSequence>>()
471→            val keys = ArrayList<CharSequence>()
472→            var values: MutableList<CharSequence>
473→            values = ArrayList()
474→            map[mainWord] = values
475→            keys.addAll(map.keys)
476→            values.addAll(Arrays.asList(*synonymMap[mainWord]!!))
477→
478→            var kinx = 0
479→            while (kinx < keys.size) {
480→                val word = keys[kinx]
481→                val synonyms = synonymMap[word]
482→                logger.trace("SYN {} : {}", word, synonyms)
483→                if (synonyms != null) {
484→                    for (sinx in synonyms.indices) {
485→                        val synonym = synonyms[sinx]
486→                        if (keys.contains(synonym)) continue
487→                        val subSynonyms = synonymMap[synonym]
488→                        if (subSynonyms != null && synonyms.isNotEmpty()) {
489→                            for (subSynonym in subSynonyms) {
490→                                if (mainWord == subSynonym) {
491→                                    values = ArrayList()
492→                                    map[synonym] = values
493→                                    keys.add(synonym)
494→                                    values.addAll(Arrays.asList(*subSynonyms))
495→                                    break
496→                                }
497→                            }
498→                        }
499→                    }
500→                }
501→                kinx++
502→            }
503→            if (map.size > 1) {
504→                normalizeSynonymMap(map)
505→            }
506→            logger.trace("MAP:{}", map)
507→            if (map.size > 1) {
508→                keys.clear()
509→                keys.addAll(TreeSet(map.keys))
510→                return keys
511→            }
512→            return null
513→        }
