516→        fun normalizeSynonymMap(map: MutableMap<CharSequence, MutableList<CharSequence>>) {
517→            val keys = ArrayList<CharSequence>()
518→            keys.addAll(map.keys)
519→            for (inx in keys.indices) {
520→                val word = keys[inx]
521→                val values = map[word]!!
522→                var vinx = 0
523→                while (vinx < values.size) {
524→                    val value = values[vinx]
525→                    if (!keys.contains(value)) {
526→                        values.removeAt(vinx)
527→                        vinx--
528→                    }
529→                    vinx++
530→                }
531→            }
