535→                val word = keys[sinx]
536→                for (tinx in keys.indices) {
537→                    if (sinx == tinx) continue
538→                    val values = map[keys[tinx]]!!
539→                    if (!values.contains(word)) {
540→                        delete.add(word)
541→                        break
542→                    }
543→                }
544→            }
545→            for (key in delete) {
