        @JvmStatic
        private fun getDictionaryFile(envBase: File, prop: JSONObject, basePath: String?): File {
            var bf: File? = null
            try {
                if (basePath != null && basePath.isNotEmpty()) {
                    bf = File(basePath)
                }
                if (bf == null || !bf.exists()) { bf = envBase }
            } catch (e: Exception) {
                logger.debug("DICTIONARY EXCEPTION : {} / {}", bf, e.message)
                bf = envBase
            }
            val dictionaryId = prop.optString(ATTR_DICTIONARY_NAME, "").trim { it <= ' ' }
            val path = prop.optString(ATTR_DICTIONARY_FILE_PATH, "").trim { it <= ' ' }
            var ret = File(bf, path)
            if (path == null || !ret.exists()) {
                ret = File(File(envBase, dictionaryPath), dictionaryId + dictionarySuffix)
            }
            return ret
        }

        @JvmStatic
        private fun getType(prop: JSONObject): Type? {
            val attribute = prop.optString(ATTR_DICTIONARY_TYPE, "").trim { it <= ' ' }
            for (type in Type.values()) {
                if (type.name.equals(attribute, ignoreCase = true)) {
                    return type
                }
            }
            return null
        }

        @JvmStatic
        private fun getIgnoreCase(prop: JSONObject): Boolean {
            return prop.optBoolean(ATTR_DICTIONARY_IGNORECASE, true)
        }

