            val attribute = prop.optString(ATTR_DICTIONARY_TOKEN_TYPE, "").trim { it <= ' ' }
            for (tokenType in TokenType.values()) {
                if (tokenType.name.equals(attribute, ignoreCase = true)) {
                    return attribute
                }
