        @JvmStatic
        fun loadDictionary(env: Environment): ProductNameDictionary {
            for (tries in 0 until 2) {
                try {
                    if (tries == 0) {
                        baseFile = ResourceResolver.getResourceRoot(ProductNameDictionary::class.java)
                    } else {
                        baseFile = env.configDir().toFile()
                    }
                    logger.debug("TESTING PRODUCT DICTIONARY BASE : {}", baseFile!!.absolutePath)
                    if (baseFile != null && baseFile!!.exists()) {
                        logger.debug("PRODUCT DICTIONARY BASE : {}", baseFile!!.absolutePath)
                    }
                } catch (e: Exception) {
                    logger.error("", e)
                    baseFile = null
                    configFile = null
                    continue
                }
                configFile = File(baseFile, ANALYSIS_PROP)
                if (configFile!!.exists()) {
                    logger.debug("DICTIONARY PROPERTIES : {}", configFile!!.absolutePath)
                    break
                } else {
                    baseFile = null
                    configFile = null
                }
            }
            val dictProp = ResourceResolver.readYmlConfig(configFile!!)
            if (dictProp == null) {
                logger.error("DICTIONARY PROPERTIES FILE NOT FOUND {}", configFile!!.absolutePath)
            }
            return loadDictionary(baseFile!!, dictProp!!)
        }

        @JvmStatic
        fun loadDictionary(baseFile: File, dictProp: JSONObject): ProductNameDictionary {
            var dictionary: Dictionary<TagProb, PreResult<CharSequence>>? = null
            var commonDictionary: ProductNameDictionary? = null
            val dictList = dictProp.optJSONArray(ATTR_DICTIONARY_LIST)
            val basePath = dictProp.optString(ATTR_DICTIONARY_BASE_PATH)

            for (inx in 0 until dictList.length()) {
                val row = dictList.optJSONObject(inx)
                if (getType(row) == Type.SYSTEM) {
                    dictionary = loadSystemDictionary(baseFile, row, basePath)
                    commonDictionary = ProductNameDictionary(dictionary)
                    break
                }
            }

            for (inx in 0 until dictList.length()) {
                val row = dictList.optJSONObject(inx)
                val dictionaryId = row.optString(ATTR_DICTIONARY_NAME)
                val type = getType(row)
                val tokenType = getTokenType(row)
                val label = getLabel(row)
                val seq = getSeq(row)
                val dictFile = getDictionaryFile(baseFile, row, basePath)
                val ignoreCase = getIgnoreCase(row)
                var sourceDictionary: SourceDictionary<*>? = null
                logger.info("Dictionary Setting Name: {}, type: {}", label, type!!.name)

                when (type) {
                    Type.SET -> {
                        val setDictionary = SetDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary!!.appendAdditionalNounEntry(setDictionary.set(), tokenType)
                        }
                        sourceDictionary = setDictionary
                    }
                    Type.MAP -> {
                        val mapDictionary = MapDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary!!.appendAdditionalNounEntry(mapDictionary.map().keys, tokenType)
                        }
                        sourceDictionary = mapDictionary
                    }
                    Type.SYNONYM, Type.SYNONYM_2WAY -> {
                        val synonymDictionary = SynonymDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary!!.appendAdditionalNounEntry(synonymDictionary.getWordSet(), tokenType)
                        }
                        sourceDictionary = synonymDictionary
                    }
                    Type.SPACE -> {
                        val spaceDictionary = SpaceDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary!!.appendAdditionalNounEntry(spaceDictionary.wordSet, tokenType)
                            val map = HashMap<CharSequence, PreResult<CharSequence>>()
                            for (e in spaceDictionary.map().entries) {
                                val preResult = PreResult<CharSequence>()
                                preResult.result = e.value
                                map[e.key] = preResult
                            }
                        }
                        sourceDictionary = spaceDictionary
                    }
                    Type.CUSTOM -> {
                        val customDictionary = CustomDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary!!.appendAdditionalNounEntry(customDictionary.getWordSet(), tokenType)
                        }
                        sourceDictionary = customDictionary
                    }
                    Type.INVERT_MAP -> {
                        val invertMapDictionary = InvertMapDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary!!.appendAdditionalNounEntry(invertMapDictionary.map().keys, tokenType)
                        }
                        sourceDictionary = invertMapDictionary
                    }
                    Type.COMPOUND -> {
                        val compoundDictionary = CompoundDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary!!.appendAdditionalNounEntry(compoundDictionary.map().keys, tokenType)
                        }
                        sourceDictionary = compoundDictionary
                    }
                    Type.SYSTEM -> { /* ignore */ }
                }
                if (sourceDictionary != null) {
                    commonDictionary!!.addDictionary(dictionaryId, sourceDictionary)
                }
            }
            return commonDictionary!!
        }

        @JvmStatic
        fun reloadDictionary() {
            if (baseFile == null || configFile == null) {
                logger.error("DICTIONARY NOT LOADED!")
                return
            }
            val localConfigFile = configFile!!
            val newCommonDictionary = loadDictionary(baseFile!!, ResourceResolver.readYmlConfig(localConfigFile)!!)
            val commonDictionary = contextStore!!.getAs(PRODUCT_NAME_DICTIONARY, ProductNameDictionary::class.java)!!
            commonDictionary.reset(newCommonDictionary)
            val dictionaryMap = commonDictionary.getDictionaryMap()

            for ((dictionaryId, dictionary) in dictionaryMap) {
                if (dictionary.javaClass.isAssignableFrom(SetDictionary::class.java)) {
                    val setDictionary = dictionary as SetDictionary
                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, SetDictionary::class.java)!!
                    setDictionary.setSet(newDictionary.set())
                } else if (dictionary.javaClass.isAssignableFrom(MapDictionary::class.java)) {
                    val mapDictionary = dictionary as MapDictionary
                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, MapDictionary::class.java)!!
                    mapDictionary.map = newDictionary.map()
                } else if (dictionary.javaClass.isAssignableFrom(SynonymDictionary::class.java)) {
                    val synonymDictionary = dictionary as SynonymDictionary
                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, SynonymDictionary::class.java)!!
                    synonymDictionary.map = newDictionary.map()
                    synonymDictionary.setWordSet(newDictionary.getWordSet())
                } else if (dictionary.javaClass.isAssignableFrom(SpaceDictionary::class.java)) {
                    val spaceDictionary = dictionary as SpaceDictionary
                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, SpaceDictionary::class.java)!!
                    spaceDictionary.map = newDictionary.map()
                    spaceDictionary.wordSet = newDictionary.wordSet
                } else if (dictionary.javaClass.isAssignableFrom(CustomDictionary::class.java)) {
                    val customDictionary = dictionary as CustomDictionary
                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, CustomDictionary::class.java)!!
                    customDictionary.setMap(newDictionary.map())
                    customDictionary.setWordSet(newDictionary.getWordSet())
                } else if (dictionary.javaClass.isAssignableFrom(CompoundDictionary::class.java)) {
                    val compoundDictionary = dictionary as CompoundDictionary
                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, CompoundDictionary::class.java)!!
                    compoundDictionary.map = newDictionary.map()
                }
                logger.info("Dictionary [{}] is reloaded!", dictionaryId)
            }
        }

        @JvmStatic
        fun compileDictionary(client: NodeClient, repo: DictionaryRepository, filter: String?, exportFile: Boolean) {
            if (baseFile == null || configFile == null) {
                logger.error("DICTIONARY NOT LOADED!")
            }

            val filters = HashSet<String>()
            if (filter != null) {
                val split = filter.trim { it <= ' ' }.split(",")
                for (item in split) {
                    filters.add(item.lowercase())
                }
            }
            logger.info("Compile Dict types: {}", filters)

            val dictProp = ResourceResolver.readYmlConfig(configFile!!)!!
            val dictList = dictProp.optJSONArray(ATTR_DICTIONARY_LIST)
            val basePath = dictProp.optString(ATTR_DICTIONARY_BASE_PATH)

            for (inx in 0 until dictList.length()) {
                val row = dictList.optJSONObject(inx)
                val dictionaryId = row.optString(ATTR_DICTIONARY_NAME)

                if (filters.size > 0 && !filters.contains(dictionaryId)) {
                    continue
                }

                val compileDictMap = compileDictionaryOne(repo, dictList, dictionaryId)
                val sourceDictionary = compileDictMap?.get("dict") as? SourceDictionary<*>
                if (sourceDictionary != null) {
                    @Suppress("UNCHECKED_CAST")
                    SearchUtil.upsertData(client, ".dsearch_dict_apply", compileDictMap as Map<String, Any>)

                    if (exportFile) {
                        val dictFile = getDictionaryFile(baseFile!!, row, basePath)
                        var ostream: java.io.OutputStream? = null
                        try {
                            ostream = FileOutputStream(dictFile)
                            sourceDictionary.writeTo(ostream)
                            logger.info("DICTIONARY FILE SAVED! {} / {}", dictionaryId, dictFile.absolutePath)
                        } catch (ignore: Exception) {
                        } finally {
                            try { ostream?.close() } catch (ignore: Exception) { }
                        }
                    }
                }
            }
            logger.debug("DICTIONARY LOAD COMPLETE! [{}]", if (filter == null) "ALL" else filter)
        }

        @JvmStatic
        fun compileDictionaryOne(repo: DictionaryRepository, dictList: JSONArray, dictionaryId: String): MutableMap<String, Any?>? {
            val result = HashMap<String, Any?>()

            for (inx in 0 until dictList.length()) {
                val row = dictList.optJSONObject(inx)
                val dictId = row.optString(ATTR_DICTIONARY_NAME)
                if (dictionaryId != dictId) {
                    continue
                }
                val type = getType(row)
                val tokenType = getTokenType(row)
                val label = getLabel(row)
                val seq = getSeq(row)
                val ignoreCase = row.optBoolean(ATTR_DICTIONARY_IGNORECASE, true)

                val source = repo.getSource(dictionaryId)

                var sourceDictionary: SourceDictionary<*>? = when (type) {
                    Type.SET -> SetDictionary(ignoreCase)
                    Type.MAP -> MapDictionary(ignoreCase)
                    Type.SYNONYM, Type.SYNONYM_2WAY -> SynonymDictionary(ignoreCase)
                    Type.SPACE -> SpaceDictionary(ignoreCase)
                    Type.CUSTOM -> CustomDictionary(ignoreCase)
                    Type.INVERT_MAP -> InvertMapDictionary(ignoreCase)
                    Type.COMPOUND -> CompoundDictionary(ignoreCase)
                    else -> null
                }

                if (sourceDictionary != null) {
                    var cnt = 0
                    while (source.hasNext()) {
                        val data = source.next()
                        var id = ""
                        var keyword = ""
                        var value = ""
                        var line: String
                        if (data[0] != null) { id = data[0].toString().trim { it <= ' ' } }
                        if (data[1] != null) { keyword = data[1].toString().trim { it <= ' ' } }
                        if (data[2] != null) { value = data[2].toString().trim { it <= ' ' } }
                        line = when {
                            type == Type.SYNONYM || type == Type.SYNONYM_2WAY -> {
                                if (keyword.isNotEmpty()) "$keyword\t$value" else value
                            }
                            type == Type.CUSTOM -> {
                                if (id.isNotEmpty()) "$keyword\t$id" else keyword
                            }
                            else -> {
                                if (value.isNotEmpty()) "$keyword\t$value" else keyword
                            }
                        }
                        sourceDictionary.addSourceLineEntry(line)
                        cnt++
                    }
                    result["cnt"] = cnt
                    logger.info("DICTIONARY LOADED! [{}] / {} / {} / {}", cnt, dictionaryId, type, tokenType)
                }
                result["dict"] = sourceDictionary
                result["type"] = dictId
                result["id"] = dictId
                return result
            }
            return null
        }

        @JvmStatic
        fun getDictionaryInfo(sourceDictionary: SourceDictionary<*>): IntArray {
            val ret = intArrayOf(0, 0)
            when {
                sourceDictionary.javaClass.isAssignableFrom(SetDictionary::class.java) -> {
                    ret[0] = (sourceDictionary as SetDictionary).set().size
                }
                sourceDictionary.javaClass.isAssignableFrom(MapDictionary::class.java) -> {
                    ret[0] = (sourceDictionary as MapDictionary).map().keys.size
                }
                sourceDictionary.javaClass.isAssignableFrom(SynonymDictionary::class.java) -> {
                    val d = sourceDictionary as SynonymDictionary
                    ret[0] = d.map().keys.size
                    ret[1] = d.getWordSet().size
                }
                sourceDictionary.javaClass.isAssignableFrom(SpaceDictionary::class.java) -> {
                    val d = sourceDictionary as SpaceDictionary
                    ret[0] = d.map().keys.size
                    ret[1] = d.wordSet.size
                }
                sourceDictionary.javaClass.isAssignableFrom(CustomDictionary::class.java) -> {
                    val d = sourceDictionary as CustomDictionary
                    ret[0] = d.map().keys.size
                    ret[1] = d.getWordSet().size
                }
                sourceDictionary.javaClass.isAssignableFrom(InvertMapDictionary::class.java) -> {
                    ret[0] = (sourceDictionary as InvertMapDictionary).map().keys.size
                }
                sourceDictionary.javaClass.isAssignableFrom(CompoundDictionary::class.java) -> {
                    val d = sourceDictionary as CompoundDictionary
                    ret[0] = d.map().keys.size
                    ret[1] = d.getWordSet().size
                }
            }
            return ret
        }

        @JvmStatic
        fun getTwowaySynonymWord(mainWord: CharSequence, synonymMap: Map<CharSequence, Array<CharSequence>>): List<CharSequence>? {
            val map = HashMap<CharSequence, MutableList<CharSequence>>()
            val keys = ArrayList<CharSequence>()
            var values: MutableList<CharSequence>
            values = ArrayList()
            map[mainWord] = values
            keys.addAll(map.keys)
            values.addAll(Arrays.asList(*synonymMap[mainWord]!!))

            var kinx = 0
            while (kinx < keys.size) {
                val word = keys[kinx]
                val synonyms = synonymMap[word]
                logger.trace("SYN {} : {}", word, synonyms)
                if (synonyms != null) {
                    for (sinx in synonyms.indices) {
                        val synonym = synonyms[sinx]
                        if (keys.contains(synonym)) continue
                        val subSynonyms = synonymMap[synonym]
                        if (subSynonyms != null && synonyms.isNotEmpty()) {
                            for (subSynonym in subSynonyms) {
                                if (mainWord == subSynonym) {
                                    values = ArrayList()
                                    map[synonym] = values
                                    keys.add(synonym)
                                    values.addAll(Arrays.asList(*subSynonyms))
                                    break
                                }
                            }
                        }
                    }
                }
                kinx++
            }
            if (map.size > 1) {
                normalizeSynonymMap(map)
            }
            logger.trace("MAP:{}", map)
            if (map.size > 1) {
                keys.clear()
                keys.addAll(TreeSet(map.keys))
                return keys
            }
            return null
        }

        @JvmStatic
        fun normalizeSynonymMap(map: MutableMap<CharSequence, MutableList<CharSequence>>) {
            val keys = ArrayList<CharSequence>()
            keys.addAll(map.keys)
            for (inx in keys.indices) {
                val word = keys[inx]
                val values = map[word]!!
                var vinx = 0
                while (vinx < values.size) {
                    val value = values[vinx]
                    if (!keys.contains(value)) {
                        values.removeAt(vinx)
                        vinx--
                    }
                    vinx++
                }
            }
            val delete = ArrayList<CharSequence>()
            logger.trace("MAP:{}", map)
            for (sinx in keys.indices) {
                val word = keys[sinx]
                for (tinx in keys.indices) {
                    if (sinx == tinx) continue
                    val values = map[keys[tinx]]!!
                    if (!values.contains(word)) {
                        delete.add(word)
                        break
                    }
                }
            }
            for (key in delete) {
                map.remove(key)
            }
            logger.trace("MAP:{}", map)
        }

        @JvmStatic
        fun isOneWaySynonym(word: CharSequence, map: Map<CharSequence, Array<CharSequence>>): Boolean {
            if (map.containsKey(word)) {
                val twoway = getTwowaySynonymWord(word, map)
                logger.trace("TWO-WAY {} = {}", word, twoway)
                for (value in map[word]!!) {
                    if (twoway != null && twoway.contains(value)) continue
                    logger.trace("ONE-WAY {} -> {}", word, value)
                    return true
                }
            }
            return false
        }

        @JvmStatic
        fun restoreDictionary(repo: DictionaryRepository, index: String) {
            val productNameDictionary = contextStore!!.getAs(PRODUCT_NAME_DICTIONARY, ProductNameDictionary::class.java)!!
            val dictionaryMap = productNameDictionary.getDictionaryMap()
            val keySet = dictionaryMap.keys
            for (key in keySet) {
                val sourceDictionary = dictionaryMap[key]!!
                logger.debug("KEY:{} / {}", key, sourceDictionary)
                when {
                    sourceDictionary.javaClass.isAssignableFrom(SetDictionary::class.java) -> {
                        val dictionary = sourceDictionary as SetDictionary
                        val words = dictionary.set()
                        repo.restore(key, dictionary.ignoreCase(), words)
                    }
                    sourceDictionary.javaClass.isAssignableFrom(MapDictionary::class.java) -> {
                        val dictionary = sourceDictionary as MapDictionary
                        val words = HashSet<CharSequence>()
                        val map = dictionary.map()
                        for (word in map.keys) {
                            val sb = StringBuilder()
                            for (value in map[word]!!) {
                                if (sb.isNotEmpty()) { sb.append(",") }
                                sb.append(value.toString().trim { it <= ' ' })
                            }
                            words.add("$word$TAB$sb")
                        }
                        repo.restore(key, dictionary.ignoreCase(), words)
                    }
                    sourceDictionary.javaClass.isAssignableFrom(SynonymDictionary::class.java) -> {
                        val dictionary = sourceDictionary as SynonymDictionary
                        val words = HashSet<CharSequence>()
                        val map = dictionary.map()
                        for (word in map.keys) {
                            val twoway = getTwowaySynonymWord(word, map)
                            run {
                                val sb = StringBuilder()
                                for (value in map[word]!!) {
                                    if (twoway != null && twoway.contains(value)) continue
                                    if (sb.isNotEmpty()) { sb.append(",") }
                                    sb.append(value.toString().trim { it <= ' ' })
                                }
                                if (sb.isNotEmpty()) {
                                    words.add("$word$TAB$sb")
                                }
                            }
                            if (twoway != null && twoway.isNotEmpty()) {
                                val sb = StringBuilder()
                                for (value in twoway) {
                                    if (sb.isNotEmpty()) { sb.append(",") }
                                    sb.append(value.toString().trim { it <= ' ' })
                                }
                                if (sb.isNotEmpty()) {
                                    words.add("$TAB$sb")
                                }
                            }
                        }
                        repo.restore(key, dictionary.ignoreCase(), words)
                    }
                    sourceDictionary.javaClass.isAssignableFrom(SpaceDictionary::class.java) -> {
                        val dictionary = sourceDictionary as SpaceDictionary
                        val words = HashSet<CharSequence>()
                        val map = dictionary.map()
                        for (word in map.keys) {
                            val sb = StringBuilder()
                            for (value in map[word]!!) {
                                if (sb.isNotEmpty()) { sb.append(" ") }
                                sb.append(value.toString().trim { it <= ' ' })
                            }
                            words.add("$word$TAB$sb")
                        }
                        repo.restore(key, dictionary.ignoreCase(), words)
                    }
                    sourceDictionary.javaClass.isAssignableFrom(CustomDictionary::class.java) -> {
                        val dictionary = sourceDictionary as CustomDictionary
                        val words = HashSet<CharSequence>()
                        val map = dictionary.map()
                        for (word in map.keys) {
                            val sb = StringBuilder()
                            for (value in map[word]!!) {
                                if (value != null) {
                                    if (sb.isNotEmpty()) { sb.append(",") }
                                    sb.append(value.toString().trim { it <= ' ' })
                                }
                            }
                            words.add("$word$TAB$word$TAB$sb")
                        }
                        repo.restore(key, dictionary.ignoreCase(), words)
                    }
                    sourceDictionary.javaClass.isAssignableFrom(InvertMapDictionary::class.java) -> {
                        val dictionary = sourceDictionary as InvertMapDictionary
                        val words = HashSet<CharSequence>()
                        val map = dictionary.map()
                        for (word in map.keys) {
                            val sb = StringBuilder()
                            for (value in map[word]!!) {
                                if (sb.isNotEmpty()) { sb.append(",") }
                                sb.append(value.toString().trim { it <= ' ' })
                            }
                            words.add("$word$TAB$sb")
                        }
                        repo.restore(key, dictionary.ignoreCase(), words)
                    }
                    sourceDictionary.javaClass.isAssignableFrom(CompoundDictionary::class.java) -> {
                        val dictionary = sourceDictionary as CompoundDictionary
                        val words = HashSet<CharSequence>()
                        val map = dictionary.map()
                        for (word in map.keys) {
                            val sb = StringBuilder()
                            for (value in map[word]!!) {
                                if (sb.isNotEmpty()) { sb.append(",") }
                                sb.append(value.toString().trim { it <= ' ' })
                            }
                            words.add("$word$TAB$sb")
                        }
                        repo.restore(key, dictionary.ignoreCase(), words)
                    }
                }
            }
            logger.debug("dictionary restore finished !")
        }

        @JvmStatic
        fun loadSystemDictionary(baseFile: File, prop: JSONObject, basePath: String?): Dictionary<TagProb, PreResult<CharSequence>> {
            val systemDictFile = getDictionaryFile(baseFile, prop, basePath)
            val st = System.nanoTime()
            val ignoreCase = getIgnoreCase(prop)
            val tagProbDictionary = TagProbDictionary(systemDictFile, ignoreCase)
            logger.debug("Product Dictionary Load {}ms >> {}", (System.nanoTime() - st) / 1000000,
                systemDictFile.name)

            tagProbDictionary.setLabel(if (prop.has("label")) prop.get("label").toString() else "")
            tagProbDictionary.setSeq(if (prop.has("seq")) prop.get("seq").toString().toInt() else 0)
            return tagProbDictionary
        }
    }
