import org.apache.logging.log4j.LogManager

import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.SYMBOL

class ProductNameParsingRule : Cloneable {

    private var extractor: KoreanWordExtractor? = null
    var option: AnalyzerOption? = null
    private var unitDictionary: SetDictionary? = null
    private var spaceDictionary: SpaceDictionary? = null
    private var unitSynonymDictionary: SynonymDictionary? = null
    private var synonymDictionary: SynonymDictionary? = null
    private var userDictionary: SetDictionary? = null
    private var compoundDictionary: CompoundDictionary? = null
    private var stopDictionary: SetDictionary? = null

    private constructor()

    constructor(extractor: KoreanWordExtractor?, dictionary: ProductNameDictionary?, option: AnalyzerOption?) {
        this.extractor = extractor
        this.option = option
        if (dictionary != null) {
            unitDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_UNIT, SetDictionary::class.java)
            synonymDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary::class.java)
            unitSynonymDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_UNIT_SYNONYM, SynonymDictionary::class.java)
            spaceDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_SPACE, SpaceDictionary::class.java)
            userDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_USER, SetDictionary::class.java)
            compoundDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_COMPOUND, CompoundDictionary::class.java)
            stopDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_STOP, SetDictionary::class.java)
        }
    }

    fun processRule(queue: MutableList<RuleEntry>, fullExtract: Boolean): Boolean {
        logger.trace("queue:{}", queue)

        if (queue.size == 1 && queue[0].type == null) {
            val entry = queue.removeAt(0)
            Entry.split(entry, queue, 0)
        }

        if (queue.size == 1 && queue[0].type == SYMBOL) {
            return false
        }

        val entry = Entry.init(queue)

        // 1. 규칙분류 시작
        RuleOne(entry, fullExtract, option!!, spaceDictionary, stopDictionary, userDictionary, unitDictionary,
            compoundDictionary, extractor).apply(queue)

        // 2. 변경타입을 생성
        RuleTwo(entry, fullExtract, option!!).apply(queue)

        // 3. 단위명 추출
        RuleThree(entry, fullExtract, option!!, unitDictionary, unitSynonymDictionary).apply(queue)

        // 4. 모델명 추출
        RuleFour(entry, fullExtract, option!!, unitDictionary).apply(queue)

        // 5. 예외규칙적용
        RuleFive(entry, fullExtract, option!!, userDictionary, compoundDictionary).apply(queue)

        return true
    }

    public override fun clone(): ProductNameParsingRule {
        val clone = ProductNameParsingRule()
        clone.extractor = this.extractor
        clone.option = this.option
        clone.unitDictionary = this.unitDictionary
        clone.spaceDictionary = this.spaceDictionary
        clone.unitSynonymDictionary = this.unitSynonymDictionary
        clone.synonymDictionary = this.synonymDictionary
        clone.userDictionary = this.userDictionary
        clone.compoundDictionary = this.compoundDictionary
        return clone
    }

    companion object {
        @JvmStatic
        private val logger = LogManager.getLogger(ProductNameParsingRule::class.java)
    }
}

