438→                            val nextNextCharType = getType(initEntry.buf[initEntry.start + 2].code)
439→                            if ((charType == ALPHA || charType == NUMBER) &&
440→                                (nextCharType == SYMBOL) &&
441→                                (nextNextCharType == ALPHA || nextNextCharType == NUMBER)) {
442→                                subQueue.clear()
443→                            } else if (charType != nextCharType && nextCharType != nextNextCharType &&
444→                                (charType == ALPHA || charType == NUMBER) &&
445→                                (nextCharType == ALPHA || nextCharType == NUMBER) &&
