package com.danawa.search.analysis.product.rule

import com.danawa.search.analysis.dict.SetDictionary
import com.danawa.search.analysis.dict.SpaceDictionary
import com.danawa.search.analysis.korean.PosTagProbEntry
import com.danawa.search.analysis.product.AnalyzerOption
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.ALPHA
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.ALPHANUM
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.AVAIL_SYMBOLS
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.COMPOUND
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.FULL_STRING
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.HANGUL
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.MAX_UNIT_LENGTH
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.MODEL_NAME
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.NUMBER
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.NUMBER_TRANS
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.SYMBOL
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.UNCATEGORIZED
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.UNIT
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.UNIT_ALPHA
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.WHITESPACE
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.containsChar
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.getTermType
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.getType
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.getUniType
import com.danawa.search.analysis.product.ProductNameTokenizer.Companion.isAlphaNum
import com.danawa.util.CharVector
import org.apache.logging.log4j.LogManager
import java.util.*

class Entry {
    var start: Int = 0
    var lastPosition: Int = 0

    companion object {
        private val logger = LogManager.getLogger(Entry::class.java)

        @JvmStatic
        fun init(queue: List<RuleEntry>): Entry {
            val e = Entry()
            if (queue.isNotEmpty()) {
                e.start = queue[0].start
                val lastOne = queue[queue.size - 1]
                e.lastPosition = lastOne.start + lastOne.length
            }
            return e
        }

        @JvmStatic
        fun merge(e0: RuleEntry, e1: RuleEntry, type: String?) {
            e0.length = (e1.start + e1.length - e0.start)
            e0.endOffset = e1.endOffset
            e0.type = type
        }

        @JvmStatic
        fun isConnected(prevEntry: RuleEntry, entry: RuleEntry): Boolean {
            return entry.start == prevEntry.start + prevEntry.length
        }

        @JvmStatic
        fun mergeNewEntry(e0: RuleEntry, e1: RuleEntry, type: String?): RuleEntry {
            val e3 = e0.clone()
            e3.length = (e1.start + e1.length - e0.start)
            e3.endOffset = e1.endOffset
            e3.type = type
            return e3
        }

        @JvmStatic
        fun mergeNewEntry(e0: RuleEntry, e1: RuleEntry, e2: RuleEntry, type: String?): RuleEntry {
            val e3 = mergeNewEntry(e0, e1, type)
            e3.length = (e2.start + e2.length - e3.start)
            e3.endOffset = e2.endOffset
            e3.type = type
            return e3
        }

        @JvmStatic
        fun addEntry(termList: MutableList<RuleEntry>, ref: CharVector, type: String?, posTag: PosTagProbEntry.PosTag?, startOffset: Int, endOffset: Int, spaceDictionary: SpaceDictionary?) {
            var entryType = type
            if (entryType == FULL_STRING) {
                // NOP
            } else if (posTag == PosTagProbEntry.PosTag.N) {
                entryType = HANGUL
            } else if (posTag == PosTagProbEntry.PosTag.DIGIT) {
                entryType = NUMBER
            } else if (posTag == PosTagProbEntry.PosTag.ALPHA) {
                entryType = ALPHA
            } else if (posTag == PosTagProbEntry.PosTag.SYMBOL) {
                entryType = SYMBOL
            } else if (posTag == null || posTag == PosTagProbEntry.PosTag.UNK) {
                entryType = UNCATEGORIZED
            }
            if (entryType != FULL_STRING && spaceDictionary != null && spaceDictionary.containsKey(ref)) {
                val offsetSt = startOffset
                val splits = spaceDictionary.get(ref)
                logger.trace("SPLIT:{}{}", "", splits)
                var position = 0
                for (sinx in splits!!.indices) {
                    val length = splits[sinx].length
                    if (sinx > 0) {
                        termList.add(RuleEntry(ref.array(), position, 0,
                            offsetSt + position, offsetSt + position, SYMBOL))
                    }
                    termList.add(RuleEntry(ref.array(), ref.offset() + position, length,
                        offsetSt + position, offsetSt + position + length, HANGUL))
                    position += length
                }
            } else {
                termList.add(RuleEntry(ref.array(), ref.offset(), ref.length(),
                    startOffset, endOffset, entryType))
            }
        }

        @JvmStatic
        fun split(entry: RuleEntry, queue: MutableList<RuleEntry>, baseInx: Int): Int {
            logger.trace("split entry ({}) : {}~{}", entry, entry.start, entry.length)
            var ptype: String? = null
            var ctype: String? = null
            var st = 0
            var addInx = 0
            val offsetStarts = entry.startOffset
            for (inx in 0 until entry.length) {
                val ch = entry.buf[entry.start + inx]
                ctype = getType(ch.code)
                if (ptype != null && ptype != ctype) {
                    val entryClone = entry.clone()
                    entryClone.start = entry.start + st
                    entryClone.length = inx - st
                    entryClone.type = ptype
                    entryClone.startOffset = offsetStarts + st
                    entryClone.endOffset = offsetStarts + st + entryClone.length
                    entryClone.modifiable = true
                    logger.trace("add splited entry : ({}) : {}~{}", entryClone, entryClone.start, entryClone.length)
                    if (entryClone.type != WHITESPACE) {
                        queue.add(baseInx + addInx, entryClone)
                        addInx++
                    }
                    if (inx > 0) {
                        entryClone.subEntry = ArrayList()
                        entryClone.synonym = null
                    }
                    st = inx
                }
                ptype = ctype
            }
            if (addInx >= 0 && st < entry.length) {
                val entryClone = entry.clone()
                if (ptype == null) {
                    ptype = ctype
                }
                entryClone.start = entry.start + st
                entryClone.length = entry.length - st
                entryClone.startOffset = offsetStarts + st
                entryClone.endOffset = offsetStarts + st + entryClone.length
                entryClone.type = ptype
                entryClone.subEntry = ArrayList()
                entryClone.synonym = null
                logger.trace("add splited entry : ({}) : {}~{}", entryClone, entryClone.start, entryClone.length)
                queue.add(baseInx + addInx, entryClone)
                addInx++
            }
            return addInx
        }

        @JvmStatic
        fun mergeQueueIndex(qinx: Int, typeContinuous: Int, queue: MutableList<RuleEntry>, subQueue: MutableList<RuleEntry>?): RuleEntry? {
            var tc = typeContinuous
            var removeInx = qinx - tc
            if (removeInx < 0) {
                removeInx = 0
                tc--
            }

            if (queue[removeInx + tc - 1].type == SYMBOL) {
                tc--
            }

            if (tc == 1) {
                logger.trace("queue has only one entry. so don't merge it")
                return null
            }

            logger.trace("queue[{}]={}", removeInx + tc - 1, queue[removeInx + tc - 1])

            val entry = queue[removeInx].clone()
            logger.trace("ENTRY-CLONE:{}", entry)
            if (entry.type == UNIT_ALPHA) {
                entry.synonym = null
            }
            entry.length = 0
            entry.endOffset = entry.startOffset
            var type = entry.type
            var subEntry: RuleEntry
            var nextEntry: RuleEntry? = null
            var dummy: RuleEntry?
            var remaining = tc
            while (remaining > 0) {
                subEntry = queue.removeAt(removeInx)
                logger.trace("pop entry:{}/{}:{}[{}~{}] / {}", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset, subEntry.synonym)
                if (type != subEntry.type || (type == UNIT_ALPHA && subEntry.type == UNIT_ALPHA)) {
                    type = null
                }
                val start = subEntry.start
                val length = subEntry.length
                val endOffset = subEntry.endOffset
                if (subQueue != null) {
                    if (subEntry.type == UNIT_ALPHA) {
                        logger.trace("subList:{}{}", "", subEntry.subEntry)
                        if (subEntry.subEntry.size > 0) {
                            var numIdx = 0
                            for (e in subEntry.subEntry) {
                                if (e.type == NUMBER || e.type == NUMBER_TRANS) {
                                    break
                                } else if (numIdx == subEntry.subEntry.size - 1) {
                                    numIdx = 0
                                }
                                numIdx++
                            }
                            val number = subEntry.subEntry.removeAt(numIdx)
                            subQueue.add(number)
                            subEntry.start += number.length
                            subEntry.length -= number.length
                            subEntry.startOffset += number.length
                            subEntry.type = ALPHA
                            if (removeInx < queue.size &&
                                queue[removeInx].also { nextEntry = it }.type == ALPHA &&
                                nextEntry!!.startOffset == subEntry.endOffset) {
                                dummy = subEntry.clone()
                                subQueue.add(dummy)
                                subEntry.length += nextEntry!!.length
                                subEntry.endOffset += nextEntry!!.length
                                queue.removeAt(removeInx)
                                remaining--
                            }
                        } else {
                            subEntry.type = ALPHANUM
                        }
                        subEntry.synonym = null
                        subQueue.add(subEntry)
                    } else {
                        subQueue.add(subEntry)
                    }
                }
                logger.trace("merge : {}[{}:{}/{}~{}]", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset)
                logger.trace("subQueue : {}", subQueue)
                entry.length = start + length - entry.start
                entry.endOffset = endOffset
                remaining--
            }
            entry.type = type
            queue.add(removeInx, entry)
            return entry
        }

