        @JvmStatic
        fun modifyRuleEntry(
            fullExtract: Boolean, option: AnalyzerOption, e0: RuleEntry, e1: RuleEntry?,
            unitCandidate: CharVector, units: Array<CharSequence>?,
            unitType: String?
        ): RuleEntry? {
            var resultE1 = e1
            val backup = e0.clone()
            if (fullExtract) {
                e0.subEntry = ArrayList()
                e0.subEntry.add(backup)
            }

            var synonyms: Array<CharSequence>? = null
            if (fullExtract && units != null && option.useForQuery()) {
                if (!(units.size == 1 && unitCandidate == units[0])) {
                    synonyms = Array(units.size) { inx ->
                        val ubuf = CharArray(e0.length + units[inx].length)
                        val unitInx = CharVector.valueOf(units[inx])!!
                        System.arraycopy(e0.buf, e0.start, ubuf, 0, e0.length)
                        System.arraycopy(unitInx.array(), unitInx.offset(), ubuf,
                            e0.length, units[inx].length)
                        CharVector(ubuf) as CharSequence
                    }
                }
            }

            if (e0.type == NUMBER_TRANS) {
                var number = e0.makeTerm(null)
                number = CharVector(number.toString().replace(",", ""))
                if (backup.length != number.length()) {
                    val unitStr = number.toString() + unitCandidate.toString()
                    resultE1 = RuleEntry(unitStr.toCharArray(), 0, unitStr.length,
                        e0.startOffset, e0.endOffset + unitCandidate.length(), UNIT)
                    e0.subEntry.add(0, resultE1)
                    logger.trace("E0:{}/E1:{}", e0, resultE1)
                }
            }

            if (fullExtract) {
                if (e0.subEntry == null) {
                    e0.subEntry = ArrayList()
                }
                if (synonyms != null && synonyms.isNotEmpty()) {
                    e0.synonym = synonyms
                }
            }

            e0.length += unitCandidate.length()
            e0.endOffset += unitCandidate.length()

            if (unitType == ALPHA) {
                e0.type = UNIT_ALPHA
            } else {
                e0.type = UNIT
            }

            return resultE1
        }

        @JvmStatic
        fun mergeSubQueue(entry: RuleEntry, subQueue: MutableList<RuleEntry>, option: AnalyzerOption, unitDictionary: SetDictionary?) {
            if (entry.type == MODEL_NAME) {
                var processed = false
                if (subQueue.size == 3) {
                    var contCnt = 0
                    val initEntry = subQueue[0].clone()
                    var prevEntry: RuleEntry = initEntry
                    for (cinx in 1 until subQueue.size) {
                        val currentEntry = subQueue[cinx]
                        if (prevEntry.startOffset + prevEntry.length != currentEntry.startOffset) {
                            break
                        }
                        initEntry.length += currentEntry.length
                        prevEntry = currentEntry
                        contCnt++
                    }
                    if (contCnt > 0 && contCnt == subQueue.size - 1) {
                        if (initEntry.length == 2) {
                            val charType = getType(initEntry.buf[initEntry.start].code)
                            val nextCharType = getType(initEntry.buf[initEntry.start + 1].code)
                            if ((charType == ALPHA || charType == NUMBER) && (nextCharType == SYMBOL)) {
                                entry.length -= 1
                                entry.endOffset -= 1
                                entry.type = charType
                                subQueue.clear()
                                processed = true
                            } else if ((charType == SYMBOL) && (nextCharType == ALPHA || nextCharType == NUMBER)) {
                                entry.start++
                                entry.startOffset++
                                entry.length--
                                entry.type = nextCharType
                                subQueue.clear()
                                processed = true
                            } else if (charType != nextCharType &&
                                (charType == ALPHA || charType == NUMBER) &&
                                (nextCharType == ALPHA || nextCharType == NUMBER)) {
                                subQueue.clear()
                                processed = true
                            }
                        } else if (initEntry.length == 3) {
                            val charType = getType(initEntry.buf[initEntry.start].code)
                            val nextCharType = getType(initEntry.buf[initEntry.start + 1].code)
                            val nextNextCharType = getType(initEntry.buf[initEntry.start + 2].code)
                            if ((charType == ALPHA || charType == NUMBER) &&
                                (nextCharType == SYMBOL) &&
                                (nextNextCharType == ALPHA || nextNextCharType == NUMBER)) {
                                subQueue.clear()
                            } else if (charType != nextCharType && nextCharType != nextNextCharType &&
                                (charType == ALPHA || charType == NUMBER) &&
                                (nextCharType == ALPHA || nextCharType == NUMBER) &&
                                (nextNextCharType == ALPHA || nextNextCharType == NUMBER)) {
                                subQueue.clear()
                            }
                            processed = true
                        }
                    }
                }
                if (!processed) {
                    if (subQueue.size == 2) {
                        val currentEntry = subQueue[0]
                        val nextEntry = subQueue[1]
                        if (currentEntry.length == 1 && nextEntry.length == 1) {
                            subQueue.clear()
                        } else if (currentEntry.type == SYMBOL) {
                            entry.start += currentEntry.length
                            entry.startOffset += currentEntry.length
                            entry.length -= currentEntry.length
                            entry.type = nextEntry.type
                        } else if (nextEntry.type == SYMBOL) {
                            entry.length -= nextEntry.length
                            entry.endOffset -= nextEntry.length
                            entry.type = currentEntry.type
                        }
                    } else if (subQueue.size == 3) {
                        val currentEntry = subQueue[0]
                        val nextEntry = subQueue[1]
                        val nextNextEntry = subQueue[2]
                        if (currentEntry.length == 1 && nextEntry.length == 1 && nextNextEntry.length == 1) {
                            if ((currentEntry.type == ALPHA || currentEntry.type == NUMBER)
                                && (nextNextEntry.type == ALPHA || nextNextEntry.type == NUMBER)) {
                                if (nextEntry.type == SYMBOL) {
                                    if (nextEntry.buf[nextEntry.start] != '+') {
                                        subQueue.clear()
                                    }
                                } else if (currentEntry.type == nextNextEntry.type) {
                                    currentEntry.length += nextEntry.length + nextNextEntry.length
                                    currentEntry.endOffset = nextNextEntry.endOffset
                                    subQueue.removeAt(2)
                                    subQueue.removeAt(1)
                                }
                            }
                        }
                    }
                }

                var continuous = 0

                logger.trace("subQueue : {}", subQueue)

                for (inx in 0..subQueue.size) {
                    var workingEntry: RuleEntry? = null
                    if (inx < subQueue.size) {
                        workingEntry = subQueue[inx]
                    }
                    if (workingEntry != null && workingEntry.length == 1 && (workingEntry.type == ALPHA || workingEntry.type == NUMBER)) {
                        logger.trace("e0:{} / {}:{}", workingEntry, inx, continuous)
                        continuous++
                    } else if (continuous > 1) {
                        var frontMatch = inx > 0 && (inx - continuous) > 0
                        if (frontMatch) {
                            val prevEntry = subQueue[inx - continuous - 1]
                            if (!(prevEntry.type == SYMBOL && prevEntry.length == 1)) {
                                frontMatch = false
                            }
                        }
                        var rearMatch = inx > 0 && inx < subQueue.size
                        if (rearMatch) {
                            val nextEntry = subQueue[inx]
                            if (!(nextEntry.type == SYMBOL && nextEntry.length == 1)) {
                                rearMatch = false
                            }
                        }
                        if (inx < subQueue.size) {
                            logger.trace("inx:{}/{} / continuous:{} / fmatch:{} / rmatch:{} / entry:{}", inx, subQueue.size, continuous, frontMatch, rearMatch, subQueue[inx])
                        }

                        @Suppress("NAME_SHADOWING")
                        var inx = inx
                        if (option.useForQuery() && ((inx - continuous == 0 && rearMatch)
                                    || (frontMatch && inx == subQueue.size)
                                    || frontMatch && rearMatch)) {
                            val pos = inx - continuous
                            val currentEntry = subQueue[pos].clone()
                            currentEntry.length += continuous - 1
                            if (continuous < 3) {
                                var subInx = 0
                                while (subInx < continuous) {
                                    val nextEntry = subQueue[pos + subInx]
                                    subQueue.removeAt(pos + subInx)
                                    currentEntry.subEntry.add(nextEntry)
                                    logger.trace("remove entry : {} , C:{}/{}/{}", nextEntry, continuous, subInx, inx)
                                    continuous--
                                    subInx--
                                    inx--
                                    subInx++
                                }
                            }
                            currentEntry.type = ALPHANUM
                            currentEntry.endOffset += currentEntry.length - 1
                            if (frontMatch && rearMatch) {
                                subQueue.add(pos + continuous, currentEntry)
                            } else if (frontMatch) {
                                subQueue.add(pos + continuous, currentEntry)
                            } else if (rearMatch) {
                                subQueue.add(pos, currentEntry)
                            }
                            logger.trace("entry : {}", currentEntry)
                            inx -= continuous
                        }
                        continuous = 0
                    } else {
                        continuous = 0
                    }
                }

                logger.trace("subQueue : {}", subQueue)

                if (option.useForQuery()) {
                    var inx = 0
                    while (inx < (subQueue.size - 1)) {
                        val currentEntry = subQueue[inx]
                        val nextEntry = subQueue[inx + 1]
                        var prevEntry: RuleEntry? = null
                        var nextNextEntry: RuleEntry? = null
                        if (inx > 0) {
                            prevEntry = subQueue[inx - 1]
                        }
                        if ((inx + 2) < subQueue.size) {
                            nextNextEntry = subQueue[inx + 2]
                        }
                        if (((prevEntry == null || (prevEntry.type == SYMBOL && prevEntry.start + prevEntry.length == currentEntry.start))
                                    && (currentEntry.type == ALPHA && nextEntry.type == NUMBER && (currentEntry.start + currentEntry.length == nextEntry.start))
                                    && (currentEntry.length == 1 && nextEntry.length == 1)
                                    && (nextNextEntry == null || (nextNextEntry.type == SYMBOL && nextEntry.start + nextEntry.length == nextNextEntry.start)))) {
                            if (logger.isTraceEnabled) {
                                logger.trace("================================================================================")
                                logger.trace("entry : {}{} // I:{} / C:{} / F:{} / R:{} / Q:{}", currentEntry.makeTerm(null), nextEntry.makeTerm(null), inx)
                                logger.trace("================================================================================")
                            }
                            currentEntry.length++
                            currentEntry.type = ALPHANUM
                            subQueue.removeAt(inx + 1)
                        }
                        inx++
                    }
                }

                logger.trace("subQueue : {}", subQueue)
                val tmpList: MutableList<RuleEntry> = ArrayList()

                var inx = 0
                while (inx < subQueue.size) {
                    val currentEntry = subQueue[inx]
                    if (currentEntry.type == SYMBOL) {
                        val c = currentEntry.buf[currentEntry.start]
                        if (c == '-' || c == '_' || c == '/') {
                            if (!option.useForQuery()) {
                                if (inx == 1 && inx + 2 < subQueue.size) {
                                    val prevEntry = subQueue[inx - 1]
                                    val nextEntry = subQueue[inx + 1]
                                    val nextNextEntry = subQueue[inx + 2]
                                    val lastEntry = subQueue[subQueue.size - 1]
                                    if (!(lastEntry.start == nextEntry.start && lastEntry.type == ALPHANUM)) {
                                        if (prevEntry.length > 0 && nextEntry.start > (prevEntry.start + prevEntry.length)
                                            && nextNextEntry.start == (nextEntry.start + nextEntry.length)
                                            && prevEntry.type == ALPHA
                                            && ((nextEntry.type == ALPHA && nextNextEntry.type == NUMBER)
                                                    || (nextEntry.type == NUMBER && nextNextEntry.type == ALPHA))) {
                                            val newEntry = RuleEntry(nextEntry.buf, nextEntry.start, lastEntry.start + lastEntry.length - nextEntry.start, nextEntry.startOffset, lastEntry.endOffset, MODEL_NAME)
                                            logger.trace("QUEUE : {}", subQueue)
                                            logger.trace("NEW-ENTRY : {}", newEntry)
                                            tmpList.add(newEntry)
                                        }
                                    } else {
                                        logger.trace("remove duplicated term : {}", lastEntry)
                                    }
                                }
                            }

                            if (inx > 0 && inx + 1 < subQueue.size) {
                                val prevEntry = subQueue[inx - 1]
                                val nextEntry = subQueue[inx + 1]
                                if (!option.useForQuery()) {
                                    var checkLevel = 0
                                    if (nextEntry.startOffset == prevEntry.endOffset + 1) {
                                        if (prevEntry.type == MODEL_NAME || prevEntry.type == ALPHANUM) {
                                            if (nextEntry.type == ALPHA || nextEntry.type == NUMBER || nextEntry.type == ALPHANUM || nextEntry.type == MODEL_NAME) {
                                                checkLevel = 2
                                            }
                                        } else if (nextEntry.type == MODEL_NAME || nextEntry.type == ALPHANUM) {
                                            if (prevEntry.type == ALPHA || prevEntry.type == NUMBER || prevEntry.type == ALPHANUM || prevEntry.type == MODEL_NAME) {
                                                checkLevel = 2
                                            }
                                        } else {
                                            if (prevEntry.type == ALPHA || prevEntry.type == NUMBER) {
                                                if (prevEntry.type == nextEntry.type) {
                                                    checkLevel = 3
                                                }
                                            }
                                        }
                                    }
                                    if (checkLevel == 2) {
                                        val lastCharTypeOfPrevEntry = getType(prevEntry.buf[prevEntry.start + prevEntry.length - 1].code)
                                        val firstCharTypeOfNextEntry = getType(nextEntry.buf[nextEntry.start].code)
                                        if (lastCharTypeOfPrevEntry == firstCharTypeOfNextEntry) {
                                            var newPrevEntryLength = 0
                                            for (sinx in prevEntry.length downTo 1) {
                                                if (getType(prevEntry.buf[prevEntry.start + sinx - 1].code) == lastCharTypeOfPrevEntry) {
                                                    newPrevEntryLength++
                                                } else {
                                                    break
                                                }
                                            }
                                            val tmpEntry = prevEntry.clone()
                                            tmpEntry.start += (prevEntry.length - newPrevEntryLength)
                                            tmpEntry.startOffset += (prevEntry.length - newPrevEntryLength)
                                            tmpEntry.length = newPrevEntryLength
                                            tmpEntry.endOffset = tmpEntry.startOffset + newPrevEntryLength
                                            tmpEntry.type = lastCharTypeOfPrevEntry
                                            @Suppress("NAME_SHADOWING")
                                            val prevEntry = tmpEntry

                                            var newNextEntryLength = 0
                                            for (sinx in 0 until nextEntry.length) {
                                                if (getType(nextEntry.buf[nextEntry.start + sinx].code) == firstCharTypeOfNextEntry) {
                                                    newNextEntryLength++
                                                } else {
                                                    break
                                                }
                                            }
                                            val tmpEntry2 = nextEntry.clone()
                                            tmpEntry2.length = newNextEntryLength
                                            tmpEntry2.endOffset = tmpEntry2.startOffset + newNextEntryLength
                                            tmpEntry2.type = firstCharTypeOfNextEntry
                                            @Suppress("NAME_SHADOWING")
                                            val nextEntry = tmpEntry2
                                            checkLevel = 3

                                            if (checkLevel == 3) {
                                                val clone = prevEntry.clone()
                                                val buf = CharArray(prevEntry.length + nextEntry.length)
                                                System.arraycopy(prevEntry.buf, prevEntry.start, buf, 0, prevEntry.length)
                                                System.arraycopy(nextEntry.buf, nextEntry.start, buf, prevEntry.length, nextEntry.length)
                                                clone.buf = buf
                                                clone.start = 0
                                                clone.length = buf.size
                                                clone.startOffset = prevEntry.startOffset
                                                clone.endOffset = nextEntry.endOffset
                                                logger.trace("TRANS-MERGE:{} / {} / {}", clone, currentEntry, prevEntry)
                                                tmpList.add(clone)
                                            }
                                        }
                                    } else if (checkLevel == 3) {
                                        val clone = prevEntry.clone()
                                        val buf = CharArray(prevEntry.length + nextEntry.length)
                                        System.arraycopy(prevEntry.buf, prevEntry.start, buf, 0, prevEntry.length)
                                        System.arraycopy(nextEntry.buf, nextEntry.start, buf, prevEntry.length, nextEntry.length)
                                        clone.buf = buf
                                        clone.start = 0
                                        clone.length = buf.size
                                        clone.startOffset = prevEntry.startOffset
                                        clone.endOffset = nextEntry.endOffset
                                        logger.trace("TRANS-MERGE:{} / {} / {}", clone, currentEntry, prevEntry)
                                        tmpList.add(clone)
                                    }
                                }
                            }
                        }
                        subQueue.removeAt(inx)
                        inx--
                    } else if (currentEntry.type == UNIT_ALPHA) {
                        logger.trace("subList:{}{}", "", currentEntry.subEntry)
                        if (currentEntry.subEntry != null && currentEntry.subEntry.size > 0) {
                            val e1 = currentEntry.subEntry.removeAt(0)
                            tmpList.add(e1)
                            currentEntry.start += e1.length
                            currentEntry.length -= e1.length
                            currentEntry.type = ALPHA
                        } else {
                            currentEntry.type = ALPHANUM
                        }
                        currentEntry.synonym = null
                    } else if (currentEntry.type == ALPHA) {
                        if (inx + 1 < subQueue.size) {
                            val e1 = subQueue[inx + 1]
                            if (e1.startOffset == currentEntry.endOffset + 1 && e1.type == ALPHA) {
                                currentEntry.length += e1.length
                                currentEntry.endOffset = e1.endOffset
                                subQueue.removeAt(inx + 1)
                            }
                        }
                    }
                    inx++
                }

                logger.trace("subQueue : {}", subQueue)

                if (subQueue.size > 2) {
                    val currentEntry = subQueue[0]
                    val nextEntry = subQueue[1]
                    logger.trace("TERM:{}/{}", nextEntry.start, nextEntry.length)
                    val finalType = getType(nextEntry.buf[nextEntry.start + nextEntry.length - 1].code)
                    if (nextEntry.start == currentEntry.start + currentEntry.length &&
                        currentEntry.length == 1 && nextEntry.length == 1 && finalType == SYMBOL
                        && ((currentEntry.type == NUMBER && nextEntry.type == ALPHA)
                                || (currentEntry.type == ALPHA && nextEntry.type == NUMBER))) {
                        subQueue.removeAt(1)
                        currentEntry.length += nextEntry.length
                        currentEntry.endOffset = currentEntry.startOffset + currentEntry.length + nextEntry.length
                        currentEntry.type = MODEL_NAME
                    }
                }

                if (!option.useForQuery()) {
                    exportByTriGram(subQueue, tmpList)
                    exportUnitGram(subQueue, tmpList, unitDictionary)
                }

                if (tmpList.size > 0) {
                    subQueue.addAll(tmpList)
                }
                Collections.sort(subQueue)
            }
        }

        private fun exportByTriGram(subQueue: MutableList<RuleEntry>, tmpList: MutableList<RuleEntry>) {
            val iter = subQueue.iterator()
            var currentEntry: RuleEntry? = null
            var nextEntry: RuleEntry? = null

            while (iter.hasNext()) {
                if (currentEntry == null) {
                    currentEntry = iter.next()
                }

                val nextNextEntry: RuleEntry?

                if (currentEntry.length == 1 && ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start].code))) || currentEntry.type == NUMBER)) {
                    if (iter.hasNext() && nextEntry == null) {
                        nextEntry = iter.next()
                        if (isConnected(currentEntry, nextEntry)) {
                            combineNextEntry(tmpList, currentEntry, nextEntry, ALPHANUM)
                        }
                    }

                    if (nextEntry != null && nextEntry.length == 1 && ((nextEntry.type == ALPHA || (nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start].code))) || nextEntry.type == NUMBER)) {
                        if ((currentEntry.type == NUMBER && (nextEntry.type == ALPHA || (nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start].code))) || ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start].code))) && nextEntry.type == NUMBER))) {
                            if (iter.hasNext()) {
                                nextNextEntry = iter.next()
                                if (isConnected(currentEntry, nextEntry) && isConnected(nextEntry, nextNextEntry)) {
                                    if (nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start].code)) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start].code)))) {
                                        combineNextNextEntry(tmpList, currentEntry, nextEntry, nextNextEntry, ALPHANUM)
                                    }
                                } else if (isConnected(nextEntry, nextNextEntry)) {
                                    if (nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start].code)) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start].code)))) {
                                        combineNextNextEntry(tmpList, nextEntry, nextNextEntry, ALPHANUM)
                                    }
                                }
                                currentEntry = nextEntry
                                nextEntry = nextNextEntry
                            }
                        } else {
                            currentEntry = nextEntry
                            nextEntry = null
                        }
                    } else if (iter.hasNext()) {
                        currentEntry = nextEntry
                        nextEntry = null
                    }
                } else if (iter.hasNext()) {
                    currentEntry = iter.next()
                }
            }
        }

        private fun exportUnitGram(subQueue: MutableList<RuleEntry>, tmpList: MutableList<RuleEntry>, unitDictionary: SetDictionary?) {
            val iter = subQueue.iterator()
            var currentEntry: RuleEntry? = null

            while (iter.hasNext()) {
                if (currentEntry == null) {
                    currentEntry = iter.next()
                }
                if (iter.hasNext()) {
                    val nextEntry = iter.next()
                    if (currentEntry.length == 1 && nextEntry.length == 1) {
                        currentEntry = nextEntry
                        continue
                    }
                    val unitCandidate = CharVector()
                    unitCandidate.init(nextEntry.buf, nextEntry.start, nextEntry.length)
                    if (unitDictionary != null && unitDictionary.set().contains(unitCandidate)) {
                        nextEntry.type = UNIT
                    }
                    if (currentEntry.type == NUMBER && (nextEntry.type == UNIT || nextEntry.type == UNIT_ALPHA)) {
                        combineNextUnitEntry(tmpList, currentEntry, nextEntry, UNIT)
                    }
                    currentEntry = nextEntry
                }
            }
        }

        private fun combineNextNextEntry(tmpList: MutableList<RuleEntry>, nextEntry: RuleEntry, nextNextEntry: RuleEntry, type: String?) {
            if (nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start].code)) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start].code)))) {
                tmpList.add(mergeNewEntry(nextEntry, nextNextEntry, type))
            }
        }

        private fun combineNextNextEntry(tmpList: MutableList<RuleEntry>, currentEntry: RuleEntry, nextEntry: RuleEntry, nextNextEntry: RuleEntry, type: String?) {
            if (nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start].code)) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start].code)))) {
                tmpList.add(mergeNewEntry(nextEntry, nextNextEntry, type))
                tmpList.add(mergeNewEntry(currentEntry, nextEntry, nextNextEntry, type))
            }
        }

        private fun combineNextEntry(tmpList: MutableList<RuleEntry>, currentEntry: RuleEntry, nextEntry: RuleEntry, type: String?) {
            if (nextEntry.length == 1 && ((nextEntry.type == ALPHA || currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start].code)) || nextEntry.type == NUMBER)) {
                if ((currentEntry.type == NUMBER && (nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start].code))) || ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start].code))) && nextEntry.type == NUMBER)) {
                    tmpList.add(mergeNewEntry(currentEntry, nextEntry, type))
                }
            }
        }

        private fun combineNextUnitEntry(tmpList: MutableList<RuleEntry>, currentEntry: RuleEntry, nextEntry: RuleEntry, type: String?) {
            if (currentEntry.type == NUMBER && nextEntry.type == UNIT) {
                tmpList.add(mergeNewEntry(currentEntry, nextEntry, type))
            }
        }
    }
}

package com.danawa.search.analysis.korean

import java.io.Serializable

class PosTagProbEntry : Serializable {
    var tagProb: TagProb? = null
    var next: PosTagProbEntry? = null
    var key: CharSequence? = null

    constructor()

    constructor(tagProb: TagProb) {
        this.tagProb = tagProb
    }

    constructor(tagProb: TagProb, cvKey: CharSequence?) {
        this.tagProb = tagProb
        this.key = cvKey
    }

    fun set(tagProb: TagProb) {
        this.tagProb = tagProb
    }

    fun get(): TagProb? = tagProb

    fun next(next: TagProb): PosTagProbEntry {
        this.next = PosTagProbEntry(next)
        this.next!!.key = this.key
        return this.next!!
    }

    fun next(): PosTagProbEntry? = next

    fun contains(posTag: TagProb): Boolean {
        var nextTagEntry: PosTagProbEntry? = this
        while (nextTagEntry != null) {
            if (nextTagEntry.get() == posTag) return true
            nextTagEntry = nextTagEntry.next()
        }
        return false
    }

    fun posContains(posTag: PosTag): Boolean {
        var nextTagEntry: PosTagProbEntry? = this
        while (nextTagEntry != null) {
            if (nextTagEntry.get()?.posTag == posTag) return true
            nextTagEntry = nextTagEntry.next()
        }
        return false
    }

    enum class PosTag {
        SOE, UNK, N, V, M, IC, J, E, EP, X, ALPHA, XPN, EOE, GUESS, DIGIT, SYMBOL
    }

    class TagProb : Serializable {
        var posTag: PosTag
            private set
        private var prob: Double

        constructor(posTag: PosTag) : this(posTag, MIN_PROB)

        constructor(posTag: PosTag, prob: Double) {
            this.posTag = posTag
            this.prob = prob
        }

        fun posTag(): PosTag = posTag
        fun prob(): Double = prob

        override fun equals(other: Any?): Boolean {
            val another = other as TagProb
            return another.posTag == this.posTag
        }

        override fun hashCode(): Int = posTag.hashCode()

        override fun toString(): String = "${posTag.name}[$prob]"

        fun toShortString(): String = posTag.name

        companion object {
            private const val serialVersionUID = 1L

            @JvmField val MAX_PROB = -5.0
            @JvmField val HIGH_PROB = -8.0
            @JvmField val P11_PROB = -11.0
            @JvmField val P12_PROB = -12.0
            @JvmField val MID_PROB = -13.0
            @JvmField val LOW_PROB = -14.0
            @JvmField val MIN_PROB = -16.0

            @JvmField val UNK = TagProb(PosTag.UNK)
            @JvmField val GUESS = TagProb(PosTag.GUESS)
            @JvmField val DIGIT = TagProb(PosTag.DIGIT, HIGH_PROB)
            @JvmField val ALPHA = TagProb(PosTag.ALPHA, HIGH_PROB)
            @JvmField val SYMBOL = TagProb(PosTag.SYMBOL)
            @JvmField val JOSA = TagProb(PosTag.J, MID_PROB)

            @JvmStatic
            fun getProb(probType: String?): Double {
                if (probType == null || probType.isEmpty()) return -1.0
                return when {
                    probType.equals("max", ignoreCase = true) -> MAX_PROB
                    probType.equals("high", ignoreCase = true) -> HIGH_PROB
                    probType.equals("mid", ignoreCase = true) -> MID_PROB
                    probType.equals("p11", ignoreCase = true) -> P11_PROB
                    probType.equals("p12", ignoreCase = true) -> P12_PROB
                    probType.equals("low", ignoreCase = true) -> LOW_PROB
                    probType.equals("min", ignoreCase = true) -> MIN_PROB
                    else -> MIN_PROB
                }
            }
        }
    }

    companion object {
        private const val serialVersionUID = 1L
    }
}

