package com.danawa.search.analysis.dict

import com.danawa.io.InputStreamDataInput
import com.danawa.io.OutputStreamDataOutput
import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag
import com.danawa.search.analysis.korean.PosTagProbEntry.TagProb
import com.danawa.search.analysis.korean.PreResult
import com.danawa.util.CharVector
import org.apache.logging.log4j.LogManager
import java.io.*
import java.util.ArrayList
import java.util.Collections
import java.util.HashMap

class TagProbDictionary : Dictionary<TagProb, PreResult<CharSequence>>, ReadableDictionary, WritableDictionary {

    private var seq: Int = 0
    private var label: String? = null
    private var ignoreCase: Boolean
    private var probMap: MutableMap<CharSequence, MutableList<TagProb>>
    private var preMap: Map<CharSequence, PreResult<CharSequence>>? = null

    constructor(ignoreCase: Boolean) {
        this.ignoreCase = ignoreCase
        probMap = HashMap()
    }

    constructor(probMap: MutableMap<CharSequence, MutableList<TagProb>>, ignoreCase: Boolean) {
        this.ignoreCase = ignoreCase
        this.probMap = HashMap(probMap)
    }

    constructor(file: File, ignoreCase: Boolean) {
        this.ignoreCase = ignoreCase
        if (!file.exists()) {
            probMap = HashMap()
            logger.error("사전파일이 존재하지 않습니다. file={}", file.absolutePath)
            return
        }
        probMap = HashMap()
        var `is`: InputStream? = null
        try {
            `is` = FileInputStream(file)
            readFrom(`is`)
        } catch (e: IOException) {
            logger.error("", e)
        } finally {
            try { `is`?.close() } catch (ignore: Exception) { }
        }
    }

    fun ignoreCase(): Boolean = ignoreCase
    override fun label(): String? = label
    override fun seq(): Int = seq
    fun setPreMap(preMap: Map<CharSequence, PreResult<CharSequence>>?) { this.preMap = preMap }

    fun appendNounEntry(entrySet: Set<CharSequence>?) {
        appendPosTagEntry(entrySet, PosTag.N, TagProb.MAX_PROB)
    }

    override fun appendAdditionalNounEntry(set: Set<CharSequence>?, tokenType: String) {
        if (set == null) return
        val prob = TagProb.getProb(tokenType)
        if (prob == -1.0) return
        appendPosTagEntry(set, PosTag.N, prob)
    }

    fun appendPosTagEntry(entrySet: Set<CharSequence>?, posTag: PosTag, prob: Double) {
        if (entrySet == null) return
        val iterator = entrySet.iterator()
        val tagProb = TagProb(posTag, prob)
        while (iterator.hasNext()) {
            val key = iterator.next()
            putAndReplaceProbMap(key, tagProb)
        }
    }

    fun addSourceEntry(line: String) {
        addSourceEntry(probMap, line, ignoreCase)
    }

    private fun putAndReplaceProbMap(key: CharSequence, tagProb: TagProb) {
        var tagProbList = probMap[key]
        if (tagProbList == null) {
            tagProbList = ArrayList(1)
            tagProbList.add(tagProb)
            probMap[key] = tagProbList
        } else {
            var foundTag = false
            for (i in tagProbList.indices) {
                val oldTagProb = tagProbList[i]
                if (oldTagProb == tagProb) {
                    if (tagProb.prob() > oldTagProb.prob()) {
                        tagProbList.removeAt(i)
                    } else {
                        foundTag = true
                    }
                    break
                }
            }
            if (!foundTag) {
                tagProbList.add(tagProb)
            }
        }
    }

    fun getUnmodifiableDictionary(): Map<CharSequence, List<TagProb>> = Collections.unmodifiableMap(probMap)

    @Throws(IOException::class)
    override fun readFrom(`in`: InputStream) {
        var inputStream = `in`
        var input: InputStreamDataInput? = null
        try {
            if (inputStream !is BufferedInputStream) {
                try { inputStream = BufferedInputStream(inputStream) } catch (ignore: Exception) { }
            }
            input = InputStreamDataInput(inputStream)
            probMap = HashMap()
            val size = input.readInt()
            for (entryInx in 0 until size) {
                val key: CharSequence = CharVector(input.readString())
                val probLength = input.readInt()
                val probs = ArrayList<TagProb>(probLength)
                for (proInx in 0 until probLength) {
                    probs.add(TagProb(PosTag.valueOf(input.readString()), input.readDouble()))
                }
                probMap[key] = probs
            }
        } finally {
            try { input?.close() } catch (ignore: IOException) { }
        }
    }

    @Throws(IOException::class)
    override fun writeTo(out: OutputStream) {
        var output: OutputStreamDataOutput? = null
        try {
            output = OutputStreamDataOutput(out)
            output.writeInt(probMap.size)
            val entrySet = probMap.entries.iterator()
            while (entrySet.hasNext()) {
                val entry = entrySet.next()
                output.writeString(entry.key.toString())
                val tagProbs = entry.value
                output.writeInt(tagProbs.size)
                for (tagProb in tagProbs) {
                    output.writeString(tagProb.posTag().toString())
                    output.writeDouble(tagProb.prob())
                }
            }
        } finally {
            try { output?.close() } catch (ignore: IOException) { }
        }
    }

    override fun find(token: CharSequence): List<TagProb>? = probMap[token]

    override fun findPreResult(token: CharSequence): PreResult<CharSequence>? {
        return preMap?.get(token)
    }

    override fun size(): Int = probMap.size

    override fun setPreDictionary(map: Map<CharSequence, PreResult<CharSequence>>) {
        this.preMap = map
    }

    fun getSeq(): Int = seq
    fun setSeq(seq: Int) { this.seq = seq }
    fun getLabel(): String? = label
    fun setLabel(label: String?) { this.label = label }

    companion object {
        private val logger = LogManager.getLogger(TagProbDictionary::class.java)

        @JvmStatic
        fun addSourceEntry(probMap: MutableMap<CharSequence, MutableList<TagProb>>, line: String, ignoreCase: Boolean) {
            if (line.startsWith("#") || line.startsWith("//") || line.isEmpty()) return
            val tmp = line.split("\t")
            if (tmp.size != 3) return

            val posTag: PosTag = when {
                tmp[1].startsWith("N") -> PosTag.N
                tmp[1].startsWith("V") -> PosTag.V
                tmp[1].startsWith("M") -> PosTag.M
                tmp[1].startsWith("IC") -> PosTag.IC
                tmp[1].startsWith("J") -> PosTag.J
                tmp[1].startsWith("E") -> PosTag.E
                tmp[1].startsWith("XPN") -> PosTag.XPN
                else -> return
            }

            val key = CharVector(tmp[0].trim { it <= ' ' })
            if (ignoreCase) {
                key.ignoreCase()
            }
            var prob = tmp[2].trim { it <= ' ' }.toDouble()
            if (key.length() == 1) {
                if (posTag == PosTag.N) {
                    if (prob > -13) {
                        prob = TagProb.MIN_PROB
                    }
                } else {
                    return
                }
            }
            var tagProbList = probMap[key]
            val tagProb = TagProb(posTag, prob)
            if (tagProbList == null) {
                tagProbList = ArrayList(1)
                probMap[key] = tagProbList
                tagProbList.add(tagProb)
            } else {
                if (tagProbList.contains(tagProb)) {
                    for (i in tagProbList.indices) {
                        val tagProb2 = tagProbList[i]
                        if (tagProb2.posTag() == tagProb.posTag()) {
                            if (tagProb2.prob() < tagProb.prob()) {
                                tagProbList.removeAt(i)
                                tagProbList.add(tagProb)
                                break
                            }
                        }
                    }
                } else {
                    tagProbList.add(tagProb)
                }
            }
        }
    }
}

