package com.danawa.search.analysis.product.rule

import com.danawa.util.CharVector
import org.apache.logging.log4j.LogManager

class RuleEntry(
    var buf: CharArray,
    var start: Int,
    var length: Int,
    var startOffset: Int,
    var endOffset: Int,
    var type: String?
) : Comparable<RuleEntry>, Cloneable {

    var modifiable: Boolean = true
    var synonym: Array<CharSequence>? = null
    var subEntry: MutableList<RuleEntry> = ArrayList()

    fun makeTerm(cv: CharVector?): CharVector {
        return makeTerm(cv, start, length)
    }

    fun makeTerm(cv: CharVector?, start: Int, length: Int): CharVector {
        val result = cv ?: CharVector()
        result.init(buf!!, start, length)
        return result
    }

    public override fun clone(): RuleEntry {
        val entry = RuleEntry(buf, start, length, startOffset, endOffset, type)
        entry.synonym = synonym
        entry.subEntry = subEntry
        return entry
    }

    override fun toString(): String {
        var str = ""
        val b = buf
        if (b != null) {
            try {
                str = "\"${String(b, start, length)}\""
            } catch (ex: Exception) {
                str = "\"${String(b)}\" [$start:$length]"
                logger.debug("EE:{}", ex.message)
            }
        }
        str += " / $type / $modifiable ($start~${start + length}/$startOffset~$endOffset)"
        if (subEntry != null) {
            str += "[${subEntry.size}]"
        }
        val syn = synonym
        if (syn != null) {
            str += "[${syn.size}]"
        }
        return str
    }

    override fun compareTo(other: RuleEntry): Int {
        var ret = this.startOffset - other.startOffset
        if (ret == 0) {
            ret = if (this.startOffset == this.endOffset) {
                -1
            } else if (other.startOffset == other.endOffset) {
                1
            } else {
                other.endOffset - this.endOffset
            }
        }
        return ret
    }

    companion object {
        private val logger = LogManager.getLogger(RuleEntry::class.java)
    }
}

