package com.danawa.search.analysis.dict

import com.danawa.io.InputStreamDataInput
import com.danawa.io.OutputStreamDataOutput
import com.danawa.util.CharVector
import java.io.*
import java.util.Arrays
import java.util.Collections
import java.util.HashSet

class SynonymDictionary : MapDictionary {

    private lateinit var wordSet: MutableSet<CharSequence>

    constructor() : this(false)

    constructor(ignoreCase: Boolean) : super(ignoreCase) {
        wordSet = HashSet()
    }

    constructor(file: File, ignoreCase: Boolean, label: String?, seq: Int, tokenType: String?, type: ProductNameDictionary.Type)
            : super(file, ignoreCase, label, seq, tokenType, type) {
        if (!::wordSet.isInitialized) wordSet = HashSet()
    }

    constructor(`is`: InputStream, ignoreCase: Boolean, label: String?, seq: Int, tokenType: String?, type: ProductNameDictionary.Type)
            : super(`is`, ignoreCase, label, seq, tokenType, type) {
        if (!::wordSet.isInitialized) wordSet = HashSet()
    }

    fun getWordSet(): MutableSet<CharSequence> = wordSet

    fun setWordSet(wordSet: MutableSet<CharSequence>) { this.wordSet = wordSet }

    fun getUnmodifiableWordSet(): Set<CharSequence> = Collections.unmodifiableSet(wordSet)

    private fun duplicateCharList(arr: Array<CharSequence>?): Array<CharSequence>? {
        if (arr != null) {
            val list = Array<CharSequence>(arr.size) { arr[it] }
            return list
        }
        return null
    }

    override fun addEntry(keyword: CharSequence?, values: Array<Any>?, columnSettingList: List<Any>?) {
        val list = ArrayList<CharSequence>(4)
        var mainWord: CharVector? = null
        if (keyword != null) {
            mainWord = CharVector(keyword.toString().trim { it <= ' ' }, ignoreCase)
            if (mainWord.length() > 0) {
                wordSet.add(mainWord)
                if (mainWord.hasWhitespaces()) {
                    for (w in CharVector.splitByWhitespace(mainWord)) {
                        wordSet.add(w)
                    }
                }
            }
        }

        if (values == null || values.isEmpty()) return
        val valueString = values[0].toString()
        val synonyms = valueString.split(",").toTypedArray()
        dedupSynonym(synonyms)
        for (k in synonyms.indices) {
            val synonym = synonyms[k].trim { it <= ' ' }
            if (synonym.isNotEmpty()) {
                val word = CharVector(synonym, ignoreCase)
                list.add(word)
                wordSet.add(word)
                if (word.hasWhitespaces()) {
                    for (w in CharVector.splitByWhitespace(word)) {
                        wordSet.add(w)
                    }
                }
            }
        }

        if (mainWord == null) {
            for (j in list.indices) {
                val key = CharVector.valueOf(list[j])!!
                var value = arrayOfNulls<CharSequence>(list.size - 1)
                var idx = 0
                for (k in list.indices) {
                    val v = list[k]
                    if (key != v) {
                        value[idx++] = v
                    }
                }
                if (idx < value.size) {
                    value = Arrays.copyOf(value, idx)
                }
                @Suppress("UNCHECKED_CAST")
                var finalValue = value as Array<CharSequence>
                if (finalValue.isNotEmpty()) {
                    var value2 = map[key]
                    if (value2 != null) {
                        value2 = duplicateCharList(value2)
                        finalValue = mergeSynonyms(value2!!, finalValue)
                    }
                    map[key] = finalValue
                    if (key.hasWhitespaces()) {
                        val noSpaceKey = CharVector(key.toString(), ignoreCase).removeWhitespaces()
                        value2 = map[noSpaceKey]
                        if (value2 != null) {
                            value2 = duplicateCharList(value2)
                            finalValue = mergeSynonyms(value2!!, finalValue)
                        }
                        map[noSpaceKey] = finalValue
                    }
                }
            }
        } else {
            var value = arrayOfNulls<CharSequence>(list.size)
            var idx = 0
            for (j in value.indices) {
                val word = list[j]
                if (mainWord != word) {
                    value[idx++] = word
                }
            }
            if (idx < value.size) {
                value = Arrays.copyOf(value, idx)
            }
            @Suppress("UNCHECKED_CAST")
            var finalValue = value as Array<CharSequence>
            if (finalValue.isNotEmpty()) {
                var value2 = map[mainWord]
                if (value2 != null) {
                    value2 = duplicateCharList(value2)
                    finalValue = mergeSynonyms(value2!!, finalValue)
                }
                map[mainWord] = finalValue
                if (mainWord.hasWhitespaces()) {
                    map[CharVector(mainWord.toString(), ignoreCase).removeWhitespaces()] = finalValue
                }
            }
        }
    }

    private fun dedupSynonym(list: Array<String>?) {
        if (list == null || list.size < 2) return
        for (i in list.indices) {
            for (j in i + 1 until list.size) {
                if (list[j].isNotEmpty() && list[i] == list[j]) {
                    list[j] = ""
                }
            }
        }
    }

    private fun mergeSynonyms(value2: Array<CharSequence>, value: Array<CharSequence>): Array<CharSequence> {
        var removedCount = 0
        val mutableValue2 = value2.toMutableList()
        for (i in value.indices) {
            for (j in i + 1 until mutableValue2.size) {
                if (mutableValue2[j] != null && value[i] == mutableValue2[j]) {
                    mutableValue2[j] = null as CharSequence
                    removedCount++
                }
            }
        }
        val newSize = mutableValue2.size + value.size - removedCount
        val list = arrayOfNulls<CharSequence>(newSize)
        var i = 0
        for (v in mutableValue2) {
            if (v != null) {
                list[i++] = v
            }
        }
        for (v in value) {
            list[i++] = v
        }
        @Suppress("UNCHECKED_CAST")
        return list as Array<CharSequence>
    }

    @Throws(IOException::class)
    override fun writeTo(out: OutputStream) {
        var outputStream = out
        if (outputStream !is BufferedOutputStream) {
            try { outputStream = BufferedOutputStream(outputStream) } catch (ignore: Exception) { }
        }
        super.writeTo(outputStream)
        val output = OutputStreamDataOutput(outputStream)
        output.writeVInt(wordSet.size)
        val synonymIter = wordSet.iterator()
        while (synonymIter.hasNext()) {
            val value = CharVector.valueOf(synonymIter.next())!!
            output.writeUString(value.array(), value.offset(), value.length())
        }
        try { outputStream.flush() } catch (ignore: Exception) { }
    }

    @Throws(IOException::class)
    override fun readFrom(`in`: InputStream) {
        var inputStream = `in`
        if (inputStream !is BufferedInputStream) {
            try { inputStream = BufferedInputStream(inputStream) } catch (ignore: Exception) { }
        }
        super.readFrom(inputStream)
        val input = InputStreamDataInput(inputStream)
        wordSet = HashSet()
        val size = input.readVInt()
        for (entryInx in 0 until size) {
            wordSet.add(CharVector(input.readUString(), ignoreCase))
        }
    }

    override fun reload(`object`: Any?) {
        if (`object` != null && `object` is SynonymDictionary) {
            super.reload(`object`)
            this.wordSet = `object`.getWordSet()
        } else {
            throw IllegalArgumentException("Reload dictionary argument error. argument = $`object`")
        }
    }
}
